void Controller::layerSong_generateBeat(uint8_t type) {
    /// @brief Generates predefined beat layouts for the active layer song bank.

    uint16_t interval;

    // 1. GENERATION TYPE DISPATCH
    // Build beat sequence according to selected generation preset.
    switch (type) {
        case 0:

            // Generate one beat at each bar boundary.
            for (int8_t i = (rhythm.bar - 1); i >= 0; i--) {
                interval = i * barInterval;
                layerSong_setBeat(selectedLayerNum, activeSongBank, interval, 0, 0, 0, 0, true);
            }
            break;

        case 1:

            // Generate off-beat pattern type-1.
            if (rhythm.measure > 1) {
                if (rhythm.measure % 2) {
                    for (int8_t i = (rhythm.measureTotal - 1); i >= 0; i--) {
                        interval = i * measureInterval;
                        if (interval % barInterval) layerSong_setBeat(selectedLayerNum, activeSongBank, i * measureInterval, 0, 0, 0, 0, false);
                    }
                } else {
                    for (int8_t i = (rhythm.bar - 1); i >= 0; i--) {
                        interval = i * barInterval + (barInterval / 2);
                        if (interval % barInterval) {
                            layerSong_setBeat(selectedLayerNum, activeSongBank, interval, 0, 0, 0, 0, false);
                        }
                    }
                }
            }
            break;

        case 2:

            // Generate off-beat pattern type-2.
            if (rhythm.measure > 1) {
                if (rhythm.measure % 2 == 0) {
                    for (int8_t i = (rhythm.measureTotal - 1); i >= 0; i--) {
                        interval = i * measureInterval;
                        if (interval % (barInterval / 2) != 0) {
                            layerSong_setBeat(selectedLayerNum, activeSongBank, i * measureInterval, 0, 0, 0, 0, false);
                        }
                    }
                }
            }
            break;

        case 3: {
            // Apply BASIC_4 fill to all existing beats (4 evenly-spaced hits per beat).
            Bank& bank = layerLibrary[selectedLayerNum].bankLibrary[activeSongBank];
            if (bank.lastActiveBeatNum != -1) {
                for (uint8_t i = 0; i <= bank.lastActiveBeatNum; i++) {
                    uint16_t endInterval = (i < bank.lastActiveBeatNum) ? bank.beatLibrary[i + 1].getStartInterval() : songInterval;
                    bank.beatLibrary[i].setEndInterval(endInterval);
                    bank.setBeatFill(i, 0, 5, 0, 0);  // fillType=0 BASIC, fillPattern=5 BASIC_4
                }
            }
        } break;

        case 4: {
            // Apply BASIC_8 fill to all existing beats (8 evenly-spaced hits per beat).
            Bank& bank = layerLibrary[selectedLayerNum].bankLibrary[activeSongBank];
            if (bank.lastActiveBeatNum != -1) {
                for (uint8_t i = 0; i <= bank.lastActiveBeatNum; i++) {
                    uint16_t endInterval = (i < bank.lastActiveBeatNum) ? bank.beatLibrary[i + 1].getStartInterval() : songInterval;
                    bank.beatLibrary[i].setEndInterval(endInterval);
                    bank.setBeatFill(i, 0, 7, 0, 0);  // fillType=0 BASIC, fillPattern=7 BASIC_8
                }
            }
        } break;
    }

    // 2. UI REFRESH
    // Redraw fill widgets when Layer Song menu is visible.
    if (menu == LAYER_SONG_MENU) {
        lcd_drawLayerSong_BeatFillTypeData(selectedLayerNum);
        lcd_drawLayerSong_BeatFillPatternData(selectedLayerNum);
        lcd_drawLayerSong_BeatFillTimeData(selectedLayerNum);
        lcd_drawLayerSong_BeatFillLevelData(selectedLayerNum);
        lcd_drawLayerSong_BeatFillGraphData(selectedLayerNum);
    }

    // 3. PLAYBACK CURSOR UPDATE
    // Recompute play beat index after generation changes.
    layerSong_calculatePlayBeatNum(selectedLayerNum, activeSongBank, playInterval);
}

void Controller::layerSong_shiftSelectedBeat(bool direction_) {
    /// @brief Shifts selected beat start position by one quantize step.

    uint16_t quantizeInterval = kQuantizeInterval[rhythm.quantize];
    Layer& layer = layerLibrary[selectedLayerNum];
    Bank& bank = layer.bankLibrary[activeSongBank];
    Beat& beat = bank.beatLibrary[selectedBeatNum];
    uint16_t interval = beat.getStartInterval();

    // 1. DIRECTIONAL SHIFT APPLY
    // Shift forward/backward when neighbor and boundary constraints allow.
    if (direction_) {
        uint16_t newInterval = interval + quantizeInterval;
        if (((selectedBeatNum == bank.lastActiveBeatNum) && (newInterval < songInterval)) || ((selectedBeatNum < bank.lastActiveBeatNum) && (newInterval < bank.beatLibrary[selectedBeatNum + 1].getStartInterval()))) {
            // Extend previous beat
            if (selectedBeatNum > 0) {
                bank.beatLibrary[selectedBeatNum - 1].setEndInterval(newInterval);
                bank.setBeatFill(selectedBeatNum - 1, 0, 0, 0, 0);
                lcd_drawBeat(selectedLayerNum, activeSongBank, (selectedBeatNum - 1), false);
            }

            // Update beat position
            lcd_clearBeat(selectedLayerNum, activeSongBank, selectedBeatNum);
            beat.setStartInterval(newInterval);
            bank.setBeatFill(selectedBeatNum, 0, 0, 0, 0);
            layerSong_setSelectedBeatFill(0, 0, 0, 0);
        }
    } else if (interval >= quantizeInterval) {
        uint16_t newInterval = interval - quantizeInterval;
        if (((selectedBeatNum == 0) && (newInterval >= 0)) || ((selectedBeatNum > 0) && (newInterval > bank.beatLibrary[selectedBeatNum - 1].getStartInterval()))) {
            // Shrink previous beat
            if (selectedBeatNum > 0) {
                bank.beatLibrary[selectedBeatNum - 1].setEndInterval(newInterval);
                bank.setBeatFill(selectedBeatNum - 1, 0, 0, 0, 0);
                lcd_drawBeat(selectedLayerNum, activeSongBank, (selectedBeatNum - 1), false);
            }

            // Update beat position
            lcd_clearBeat(selectedLayerNum, activeSongBank, selectedBeatNum);
            beat.setStartInterval(newInterval);
            bank.setBeatFill(selectedBeatNum, 0, 0, 0, 0);
            layerSong_setSelectedBeatFill(0, 0, 0, 0);
        }
    }
}

void Controller::layerSong_resetSelectedBeat() {
    /// @brief Removes selected beat, compacts beat list, and refreshes selection/UI.

    // 1. SELECTION & BANK VALIDATION
    // Continue only when selected layer and bank contain active beats.
    if (selectedLayerNum != -1) {
        Layer& layer = layerLibrary[selectedLayerNum];
        Bank& bank = layer.bankLibrary[activeSongBank];
        if (bank.lastActiveBeatNum != -1) {
            // 2. PREVIOUS BEAT REPAIR
            // Adjust previous beat end interval after removing current beat.
            if (selectedBeatNum > 0) {
                if (selectedBeatNum != bank.lastActiveBeatNum) {
                    bank.beatLibrary[selectedBeatNum - 1].setEndInterval(bank.beatLibrary[selectedBeatNum + 1].getStartInterval());
                } else {
                    bank.beatLibrary[selectedBeatNum - 1].setEndInterval(songInterval);
                }
                bank.setBeatFill(selectedBeatNum - 1, 0, 0, 0, 0);
                lcd_drawBeat(selectedLayerNum, activeSongBank, (selectedBeatNum - 1), false);
            }

            // 3. BEAT CLEAR & REORDER
            // Clear target beat, reset slot, and compact active list.
            lcd_clearBeat(selectedLayerNum, activeSongBank, selectedBeatNum);
            bank.resetBeat(selectedBeatNum);
            layerSong_arrangeActiveBeats(selectedLayerNum, activeSongBank, false, true, true, true);

            // 4. SELECTION RECALCULATION
            // Select previous valid beat or set selection to none.
            if (bank.lastActiveBeatNum != -1) {
                if (selectedBeatNum == 0) {
                    selectedBeatNum = bank.lastActiveBeatNum;
                } else {
                    selectedBeatNum -= 1;
                }
                lcd_drawBeat(selectedLayerNum, activeSongBank, selectedBeatNum, true);
            } else {
                selectedBeatNum = -1;
            }

            // 5. UI REFRESH
            // Redraw fill widgets for updated beat state.
            lcd_drawLayerSong_BeatFillTypeData(selectedLayerNum);
            lcd_drawLayerSong_BeatFillPatternData(selectedLayerNum);
            lcd_drawLayerSong_BeatFillTimeData(selectedLayerNum);
            lcd_drawLayerSong_BeatFillLevelData(selectedLayerNum);
            lcd_drawLayerSong_BeatFillGraphData(selectedLayerNum);
        }
    }
}

void Controller::layerSong_resetBeats(uint8_t layerNum_, uint8_t bankTab_, uint16_t startInterval_) {
    /// @brief Resets beats whose start interval is at/after given position.

    Layer& layer = layerLibrary[layerNum_];
    Bank& bank = layer.bankLibrary[bankTab_];

    // 1. ACTIVE BANK VALIDATION
    // Continue only when target bank contains active beats.
    if (bank.lastActiveBeatNum != -1) {
        bool reorder = false;
        for (uint8_t i = 0; i <= bank.lastActiveBeatNum; i++) {
            Beat& beat = bank.beatLibrary[i];
            if (beat.getStartInterval() >= startInterval_) {
                // 2. TARGET BEAT RESET
                // Extend previous beat and reset current beat slot.
                if (i > 0) {
                    bank.beatLibrary[i - 1].setEndInterval(songInterval);
                    bank.setBeatFill(i - 1, 0, 0, 0, 0);
                }
                bank.resetBeat(i);
                reorder = true;
            }
        }

        // 3. ACTIVE LIST ARRANGEMENT
        // Rebuild active beat list and playback state after resets.
        layerSong_arrangeActiveBeats(layerNum_, bankTab_, reorder, reorder, reorder, true);
    }
}

void Controller::layerSong_resetAllBeats(uint8_t layerNum_, uint8_t bankTab_) {
    /// @brief Resets every beat slot in the target layer song bank.

    Layer& layer = layerLibrary[layerNum_];
    Bank& bank = layer.bankLibrary[bankTab_];

    // 1. ACTIVE BANK VALIDATION
    // Continue only when target bank contains active beats.
    if (bank.lastActiveBeatNum != -1) {
        // 2. FULL BANK RESET
        // Clear all beat slots and reset runtime beat pointers.
        for (uint16_t i = 0; i < kBeatLibrarySize; i++) {
            bank.resetBeat(i);
        }
        bank.lastActiveBeatNum = -1;
        bank.playBeatNum = -1;
        lcd_clearSong(layerNum_, bankTab_);

        // 3. CONDITIONAL UI REFRESH
        // Refresh beat widgets when target bank is currently visible.
        if ((selectedLayerNum == layerNum_) && (activeSongBank == bankTab_) && (menu = LAYER_SONG_MENU)) {
            selectedBeatNum = -1;
            lcd_drawLayerSong_BeatFillTypeData(selectedLayerNum);
            lcd_drawLayerSong_BeatFillPatternData(selectedLayerNum);
            lcd_drawLayerSong_BeatFillTimeData(selectedLayerNum);
            lcd_drawLayerSong_BeatFillLevelData(selectedLayerNum);
            lcd_drawLayerSong_BeatFillGraphData(selectedLayerNum);
        }
    }
}

void Controller::layerSong_quantizeActiveBeats(uint8_t layerNum_, uint8_t bankTab_) {
    /// @brief Quantizes active beats to current rhythm grid and rebuilds beat ordering.

    uint16_t quantizeInterval = kQuantizeInterval[rhythm.quantize];

    // 1. ACTIVE BEAT QUANTIZATION
    // Snap start/end intervals to quantize grid for active beats.
    for (uint8_t i = 0; i < kLayerLibrarySize; i++) {
        Layer& layer = layerLibrary[i];
        Bank& bank = layer.bankLibrary[bankTab_];
        if (bank.lastActiveBeatNum != -1) {
            for (uint8_t j = 0; j < kBeatLibrarySize; j++) {
                Beat& beat = bank.beatLibrary[j];
                if (beat.getActive()) {
                    uint16_t startInterval = beat.getStartInterval();
                    uint16_t endInterval = beat.getEndInterval();

                    // Compensate interval for better quantization.
                    if (startInterval != 0) startInterval -= 1;
                    if (endInterval != 0) endInterval -= 1;
                    startInterval = ((startInterval / quantizeInterval) + ((startInterval % quantizeInterval) / (quantizeInterval / 2))) * quantizeInterval;
                    endInterval = ((endInterval / quantizeInterval) + ((endInterval % quantizeInterval) / (quantizeInterval / 2))) * quantizeInterval;
                    if (endInterval > songInterval) {
                        endInterval = songInterval;
                    }
                    if (startInterval != songInterval) {
                        beat.setStartInterval(startInterval);
                        beat.setEndInterval(endInterval);
                        bank.setBeatFill(j, 0, 0, 0, 0);
                    } else {
                        bank.resetBeat(j);
                    }
                }
            }

            // 2. ACTIVE LIST ARRANGEMENT
            // Reorder and normalize beat list after quantization pass.
            layerSong_arrangeActiveBeats(layerNum_, bankTab_, true, true, true, true);
        }
    }
}

void Controller::layerSong_arrangeActiveBeats(uint8_t layerNum_, uint8_t bankTab_, bool duplicate_, bool collect_, bool sort_, bool lastFill_) {
    /// @brief Normalizes active beat list via duplicate removal, collect, sort, and fill rules.

    Layer& layer = layerLibrary[layerNum_];
    Bank& bank = layer.bankLibrary[bankTab_];

    // 1. ACTIVE BANK VALIDATION
    // Continue only when target bank contains active beats.
    if (bank.lastActiveBeatNum != -1) {
        // 2. DUPLICATE REMOVAL PHASE
        // Remove beats that share the same start interval.
        if (duplicate_) {
            for (uint8_t i = 0; i < kBeatLibrarySize; i++) {
                Beat& beat = bank.beatLibrary[i];
                if (beat.getActive()) {
                    uint16_t beatStartInterval = beat.getStartInterval();
                    for (uint8_t j = i + 1; j < kBeatLibrarySize; j++) {
                        Beat& nextBeat = bank.beatLibrary[j];
                        if (nextBeat.getActive()) {
                            uint16_t nextStartInterval = bank.beatLibrary[j].getStartInterval();
                            if (nextStartInterval == beatStartInterval) {
                                bank.resetBeat(j);
                            }
                        }
                    }
                }
            }
        }

        // 3. COMPACT PHASE
        // Collect active beats contiguously and update last-active index.
        if (collect_) {
            Beat tempLibrary[kBeatLibrarySize];
            int8_t tempCounter = -1;
            for (uint8_t i = 0; i < kBeatLibrarySize; i++) {
                if (bank.beatLibrary[i].getActive()) {
                    tempCounter += 1;
                    tempLibrary[tempCounter] = bank.beatLibrary[i];
                }
            }
            for (uint8_t j = 0; j < kBeatLibrarySize; j++) {
                bank.beatLibrary[j] = tempLibrary[j];
            }
            bank.lastActiveBeatNum = tempCounter;
        }

        // 4. SORT PHASE
        // Sort active beats by start interval and rebuild end intervals.
        if ((sort_) && (bank.lastActiveBeatNum > 0)) {
            // Sort beats.
            uint8_t min;
            Beat temp;
            for (uint8_t i = 0; i < (bank.lastActiveBeatNum - 1); i++) {
                min = i;
                for (uint8_t j = i + 1; j < bank.lastActiveBeatNum; j++) {
                    if (bank.beatLibrary[j].getStartInterval() < bank.beatLibrary[min].getStartInterval()) {
                        min = j;
                    }
                }
                temp = bank.beatLibrary[i];
                bank.beatLibrary[i] = bank.beatLibrary[min];
                bank.beatLibrary[min] = temp;
            }

            // Update end intervals.
            for (uint8_t k = 0; k < bank.lastActiveBeatNum; k++) {
                bank.beatLibrary[k].setEndInterval(bank.beatLibrary[k + 1].getStartInterval());
            }
            bank.beatLibrary[bank.lastActiveBeatNum].setEndInterval(songInterval);

            // Update fill parameters.
            for (uint8_t l = 0; l < bank.lastActiveBeatNum; l++) {
                uint8_t fillType = bank.beatLibrary[l].getFillType();
                uint8_t fillPattern = bank.beatLibrary[l].getFillPattern();
                uint8_t fillTime = bank.beatLibrary[l].getFillTime();
                uint8_t fillLevel = bank.beatLibrary[l].getFillLevel();
                bank.setBeatFill(l, fillType, fillPattern, fillTime, fillLevel);
            }
        }

        // 5. LAST-BEAT FILL RULE
        // Clear invalid fill on last beat when end interval is not song end.
        if (lastFill_) {
            if (bank.lastActiveBeatNum != -1) {
                Beat& beat = bank.beatLibrary[bank.lastActiveBeatNum];
                if ((beat.getFillType() != 0) && (beat.getEndInterval() != songInterval)) {
                    bank.setBeatFill(bank.lastActiveBeatNum, 0, 0, 0, 0);
                }
            }
        }

        // 6. PLAYBACK POINTER UPDATE
        // Recalculate play beat pointer after arrangement.
        layerSong_calculatePlayBeatNum(layerNum_, bankTab_, playInterval);
    }
}

void Controller::layerSong_calculateLastActiveBeatNum(uint8_t layerNum_, uint8_t bankTab_) {
    /// @brief Calculates and stores the last active beat index for target bank.

    int8_t lastActiveBeatNum = -1;
    Layer& layer = layerLibrary[layerNum_];
    Bank& bank = layer.bankLibrary[bankTab_];

    // 1. LAST ACTIVE BEAT SCAN
    // Walk beat list until first inactive slot and keep last active index.
    for (uint16_t i = 0; i < kBeatLibrarySize; i++) {
        if (bank.beatLibrary[i].getActive()) {
            lastActiveBeatNum = i;
        } else {
            break;
        }
    }
    bank.lastActiveBeatNum = lastActiveBeatNum;
}

void Controller::layerSong_calculatePlayBeatNum(uint8_t layerNum_, uint8_t bankTab_, uint16_t playInterval_) {
    /// @brief Resolves next playable beat/micro-beat index for given play interval.

    Layer& layer = layerLibrary[layerNum_];
    Bank& bank = layer.bankLibrary[bankTab_];

    // 1. ACTIVE BEAT VALIDATION
    // Continue only when bank contains at least one active beat.
    if (bank.lastActiveBeatNum != -1) {
        // 2. FILL-ENABLED SEARCH
        // Resolve next beat/micro-step when fill mode is enabled.
        if (layer.fill) {
            bool findFlag = false;
            for (uint8_t i = 0; i <= bank.lastActiveBeatNum; i++) {
                Beat& beat = bank.beatLibrary[i];
                uint8_t fillType = beat.getFillType();
                uint8_t fillPattern = beat.getFillPattern();

                // Simple beat processing.
                if ((fillType == 0) && (fillPattern <= 2)) {
                    if ((beat.getActive()) && (beat.getStartInterval() >= playInterval)) {
                        bank.playBeatNum = i;
                        bank.playBeatMicroNum = -1;
                        findFlag = true;
                        break;
                    }
                    if (findFlag) {
                        break;
                    }
                }

                // Complex fill processing.
                else {
                    uint8_t fillTarget = beat.getFillTarget();
                    if (fillTarget != NULL_FILL_TARGET) {
                        BeatFill& beatFillRef = bank.beatFillLibrary[fillTarget];
                        for (uint8_t j = 0; j < beatFillRef.getStepSize(); j++) {
                            BeatMicro& beatMicro = beatFillRef.beatMicroLibrary[j];
                            if ((beat.getActive()) && (beatMicro.getActive()) && (beatMicro.getInterval() >= playInterval)) {
                                bank.playBeatNum = i;
                                bank.playBeatMicroNum = j;
                                findFlag = true;
                                break;
                            }
                        }
                    }
                    if (findFlag) {
                        break;
                    }
                }
            }

            if (!findFlag) {
                Beat& beat = bank.beatLibrary[0];
                bank.playBeatNum = 0;
                bank.playBeatMicroNum = ((beat.getFillType() == 0) && (beat.getFillPattern() <= 2)) ? -1 : 0;
            }
        }

        // 3. FILL-DISABLED SEARCH
        // Resolve next base beat when fill mode is disabled.
        else {
            bool findFlag = false;
            for (uint8_t i = 0; i <= bank.lastActiveBeatNum; i++) {
                Beat& beat = bank.beatLibrary[i];
                if ((beat.getActive()) && (beat.getStartInterval() >= playInterval)) {
                    bank.playBeatNum = i;
                    bank.playBeatMicroNum = -1;
                    findFlag = true;
                    break;
                }
            }

            if (!findFlag) {
                bank.playBeatNum = 0;
                bank.playBeatMicroNum = -1;
            }
        }
    } else {
        // 4. EMPTY BANK FALLBACK
        // Mark play pointers as invalid when no active beats exist.
        bank.playBeatNum = -1;
        bank.playBeatMicroNum = -1;
    }
}

void Controller::layerSong_calculateBeatFill(uint8_t layerNum_, uint8_t bankTab_, uint8_t beatNum_, uint8_t fillType_, uint8_t fillPattern_, uint8_t fillTime_, uint8_t fillLevel_) {
    /// @brief Recomputes selected beat end interval and applies fill parameters.

    Layer& layer = layerLibrary[layerNum_];
    Bank& bank = layer.bankLibrary[bankTab_];
    Beat& beat = bank.beatLibrary[beatNum_];
    uint16_t endInterval;

    // 1. END INTERVAL RESOLUTION
    // Resolve end interval from next beat or song boundary.
    (beatNum_ < bank.lastActiveBeatNum) ? endInterval = bank.beatLibrary[beatNum_ + 1].getStartInterval() : endInterval = songInterval;

    // 2. FILL PARAMETER APPLY
    // Store resolved end interval and update fill parameters.
    beat.setEndInterval(endInterval);
    bank.setBeatFill(beatNum_, fillType_, fillPattern_, fillTime_, fillLevel_);
}

void Controller::layerSong_calculateBeatFillTime(uint8_t layerNum_, uint8_t bankTab_, uint8_t beatNum_, uint8_t fillTime_) {
    /// @brief Updates fill-time value for target beat while preserving other fill fields.

    // 1. FILL TIME UPDATE
    // Apply new fill-time while keeping existing type/pattern/level.
    Layer& layer = layerLibrary[layerNum_];
    Bank& bank = layer.bankLibrary[bankTab_];
    Beat& beat = bank.beatLibrary[beatNum_];
    bank.setBeatFill(beatNum_, beat.getFillType(), beat.getFillPattern(), fillTime_, beat.getFillLevel());
}

void Controller::layerSong_calculateBeatFillLevel(uint8_t layerNum_, uint8_t bankTab_, uint8_t beatNum_, uint8_t fillLevel_) {
    /// @brief Updates fill-level value for target beat while preserving other fill fields.

    // 1. FILL LEVEL UPDATE
    // Apply new fill-level while keeping existing type/pattern/time.
    Layer& layer = layerLibrary[layerNum_];
    Bank& bank = layer.bankLibrary[bankTab_];
    Beat& beat = bank.beatLibrary[beatNum_];
    bank.setBeatFill(beatNum_, beat.getFillType(), beat.getFillPattern(), beat.getFillTime(), fillLevel_);
}

void Controller::layerSong_copy() {
    /// @brief Copies active bank beat data of selected layer to clipboard buffer.

    // 1. SELECTION VALIDATION
    // Continue only when selected layer index is valid.
    if (selectedLayerNum != -1) {
        // 2. CLIPBOARD SNAPSHOT
        // Mark clipboard active and copy beat library data.
        layerSongCopy.copyActive = true;
        for (uint8_t i = 0; i < kBeatLibrarySize; i++) {
            layerSongCopy.lastActiveBeatNum = layerLibrary[selectedLayerNum].bankLibrary[activeSongBank].lastActiveBeatNum;
            layerSongCopy.beatLibrary[i] = layerLibrary[selectedLayerNum].bankLibrary[activeSongBank].beatLibrary[i];
        }
    }
}

void Controller::layerSong_paste() {
    /// @brief Pastes clipboard beat data into selected layer active song bank.

    // 1. CLIPBOARD & TARGET VALIDATION
    // Continue only when clipboard is active and selection is valid.
    if ((layerSongCopy.copyActive) && (selectedLayerNum != -1)) {
        Layer& layer = layerLibrary[selectedLayerNum];

        // 2. EXISTING DATA CLEANUP
        // Clear current bank beats before paste operation.
        if (layer.bankLibrary[activeSongBank].lastActiveBeatNum != -1) layerSong_resetAllBeats(selectedLayerNum, activeSongBank);

        // 3. CLIPBOARD APPLY
        // Recreate beats from clipboard entries within song range.
        if (layerSongCopy.lastActiveBeatNum != -1) {
            for (int8_t i = layerSongCopy.lastActiveBeatNum; i >= 0; i--) {
                uint16_t startInterval = layerSongCopy.beatLibrary[i].getStartInterval();
                uint8_t fillType = layerSongCopy.beatLibrary[i].getFillType();
                uint8_t fillPattern = layerSongCopy.beatLibrary[i].getFillPattern();
                uint8_t fillTime = layerSongCopy.beatLibrary[i].getFillTime();
                uint8_t fillLevel = layerSongCopy.beatLibrary[i].getFillLevel();
                if (startInterval < songInterval) layerSong_setBeat(selectedLayerNum, activeSongBank, startInterval, fillType, fillPattern, fillTime, fillLevel, true);
            }

            // 4. SELECTION & UI REFRESH
            // Recompute selection/play pointers and redraw menu widgets.
            if (layer.bankLibrary[activeSongBank].lastActiveBeatNum != -1) {
                selectedBeatNum = 0;
                layerSong_calculateLastActiveBeatNum(selectedLayerNum, activeSongBank);
                layerSong_calculatePlayBeatNum(selectedLayerNum, activeSongBank, playInterval);
                lcd_drawLayerSong_BeatFillTypeData(selectedLayerNum);
                lcd_drawLayerSong_BeatFillPatternData(selectedLayerNum);
                lcd_drawLayerSong_BeatFillTimeData(selectedLayerNum);
                lcd_drawLayerSong_BeatFillLevelData(selectedLayerNum);
                lcd_drawLayerSong_BeatFillGraphData(selectedLayerNum);
                lcd_drawSong(selectedLayerNum, activeSongBank);
            }
        }
    }
}

void Controller::layerSong_selectBank(uint8_t bankNum_) {
    /// @brief Selects active song bank and refreshes all layer song visuals/play pointers.

    // 1. INPUT VALIDATION
    // Accept only values inside configured song-bank limits.
    if ((bankNum_ >= kMinSongBank) && (bankNum_ <= kMaxSongBank)) {
        // 2. BANK SWITCH CONDITION
        // Continue only when requested bank differs from active bank.
        if (bankNum_ != activeSongBank) {
            uint8_t preBankNum = activeSongBank;
            activeSongBank = bankNum_;
            lcd_drawSongBankTab(bankNum_, false);

            // 3. ACTIVE MENU REFRESH
            // Refresh selected beat and visible Layer Song widgets.
            if (menu == LAYER_SONG_MENU) {
                (layerLibrary[selectedLayerNum].bankLibrary[activeSongBank].lastActiveBeatNum != -1) ? selectedBeatNum = 0 : selectedBeatNum = -1;
                lcd_drawLayerSong_BeatFillTypeData(selectedLayerNum);
                lcd_drawLayerSong_BeatFillGraphData(selectedLayerNum);
                lcd_drawLayerSong_BeatFillTimeData(selectedLayerNum);
                lcd_drawLayerSong_BeatFillLevelData(selectedLayerNum);
                lcd_drawLayerSong_BeatFillGraphData(selectedLayerNum);
            }

            // 4. GLOBAL LAYER REFRESH
            // Redraw all layer song lanes and update play pointers.
            for (uint8_t i = 0; i < kLayerLibrarySize; i++) {
                lcd_clearSong(i, preBankNum);
                lcd_drawSong(i, activeSongBank);
                layerSong_calculatePlayBeatNum(i, activeSongBank, playInterval);
            }
        }
    }
}

void Controller::layerSong_triggerBank(uint8_t bankNum_) {
    /// @brief Arms/cancels bank shift trigger for next song loop boundary.

    // 1. INPUT VALIDATION
    // Accept only values inside configured song-bank limits.
    if ((bankNum_ >= kMinSongBank) && (bankNum_ <= kMaxSongBank)) {
        // 2. SHIFT ARM/CANCEL
        // Arm bank shift when target differs, cancel when same bank is retriggered.
        if (bankNum_ != activeSongBank) {
            bankShiftFlag = true;
            targetSongBank = bankNum_;
            lcd_drawSongBankTab(bankNum_, true);
        } else if ((bankNum_ == activeSongBank) && (bankShiftFlag) && (targetSongBank != activeSongBank)) {
            bankShiftFlag = false;
            targetSongBank = bankNum_;
            lcd_drawSongBankTab(bankNum_, false);
        }
    }
}

////////////////////////////////////////////////////////////////////////////////
/* Play Functions ------------------------------------------------------------*/
////////////////////////////////////////////////////////////////////////////////

void Controller::record() {
    /// @brief Toggles recording state and synchronizes transport/icon state.

    // 1. TRANSPORT STATE BRANCH
    // Resolve behavior for idle, recording, and play-only states.
    if ((!playActive) && (!recordActive)) {
        bool usePrecount = false;

        // 3. IDLE -> RECORD+PLAY START
        // Start playback/recording and optionally arm metronome precount.
        // In slave mode the external clock defines the start point; skip precount.
        if ((metronome.active) && (metronome.precount) && (!io.sync.slaveMode)) {
            usePrecount = true;
            metronome.precountState = true;
            metronome.precounter = 0;
            metronome.countDown = rhythm.measure;

            // Clear any stale pending hits from a previous precount take.
            for (uint8_t i = 0; i < kLayerLibrarySize; i++) precountPendingBeat[i] = false;
        }

        // Reset LFO counters to start modulation cycles from known phase.
        for (uint8_t i = 0; i < kLfoLibrarySize; i++) {
            lfoLibrary[i].sampleCounter = 0;
        }

        // Enqueue MIDI Start only when playback actually begins.
        // If precount is active, defer transmission until precount completes.
        if (io.midi.txTransport) {
            if (usePrecount) {
                io.midi.txStartPending = true;
            } else {
                static const uint8_t kMidiStart = 0xFA;
                enqueueMidiTx(&kMidiStart, 1);
                io.midi.txStartPending = false;
            }
        }

        // Update transport flags and front-panel icons.
        recordActive = true;
        recordIcon.flag = true;
        recordIcon.mode = true;
        stopFlag = false;
        resetFlag = false;
        playActive = true;
        if (io.syncOut == 1) {
            HAL_GPIO_WritePin(SYNC_OUT_GATE_GPIO_Port, SYNC_OUT_GATE_Pin, GPIO_PIN_SET);
        }
        resetIcon.flag = true;
        resetIcon.mode = false;
        playIcon.flag = true;
        playIcon.mode = true;
        stopIcon.flag = true;
        stopIcon.mode = false;
    }

    // 4. PLAY+RECORD -> PLAY ONLY
    // Disable recording while preserving playback state.
    else if ((playActive) && (recordActive)) {
        // If still in precount, stop entire transport instead of toggling record.
        if (metronome.precountState) {
            stop();
        } else {
            recordActive = false;
            stopFlag = false;
            resetFlag = false;
            recordIcon.flag = true;
            recordIcon.mode = false;
        }
    }

    // 5. PLAY ONLY -> PLAY+RECORD
    // Re-enable recording while playback is already running.
    else if ((playActive) && (!recordActive)) {
        recordActive = true;
        stopFlag = false;
        resetFlag = false;
        recordIcon.flag = true;
        recordIcon.mode = true;
    }
}

void Controller::play() {
    /// @brief Starts playback transport and refreshes related transport visuals/state.

    // 1. MIDI START TRANSMISSION
    // Enqueue MIDI Start (0xFA) before the clock timer fires its first tick.
    if (io.midi.txTransport) {
        static const uint8_t kMidiStart = 0xFA;
        enqueueMidiTx(&kMidiStart, 1);
        io.midi.txStartPending = false;
    }

    // 3. HARDWARE TIMER SYNCHRONIZATION
    // Force midi clock (tim4) and sequencer (tim15) to reset phase for perfect alignment.
    htim4.Instance->EGR = TIM_EGR_UG;
    htim15.Instance->EGR = TIM_EGR_UG;

    // 2. LFO RESET
    // Reset LFO counters to keep modulation start deterministic.
    for (uint8_t i = 0; i < kLfoLibrarySize; i++) {
        lfoLibrary[i].sampleCounter = 0;
    }

    // 3. TRANSPORT STATE UPDATE
    // Set playback flags and transport icons for running state.
    stopFlag = false;
    resetFlag = false;
    playActive = true;
    resetIcon.flag = true;
    resetIcon.mode = false;
    playIcon.flag = true;
    playIcon.mode = true;
    stopIcon.flag = true;
    stopIcon.mode = false;

    // 4. MODE-B GATE
    // MODE-B: gate goes high while transport is running.
    if (io.syncOut == 2) {
        HAL_GPIO_WritePin(SYNC_OUT_GATE_GPIO_Port, SYNC_OUT_GATE_Pin, GPIO_PIN_SET);
        io.sync.txTrsTickCounter = 0;
    }

    // 5. PLAY POINTER RECALCULATION
    // Recompute initial play beat pointer from current play interval.
    layerSong_calculatePlayBeatNum(0, 0, playInterval);
}

void Controller::stop() {
    /// @brief Stops transport, clears pending transitions, and resets transport icons.

    // 1. MIDI STOP TRANSMISSION
    // Enqueue MIDI Stop (0xFC) when MIDI sync TX is active.
    if (io.midi.txTransport) {
        static const uint8_t kMidiStop = 0xFC;
        enqueueMidiTx(&kMidiStop, 1);
    }

    // 3. PRECOUNT STATE RESET
    // Clear metronome precount counters and hide countdown UI.
    if (metronome.precountState) {
        metronome.precountState = false;
        metronome.precounter = 0;
        metronome.countDownFlag = false;
        metronome.countDown = 0;
        lcd_clearCountDown();
    }

    // 3. BANK SHIFT CANCEL
    // Cancel pending bank shift and restore active bank indicator.
    if (bankShiftFlag) {
        bankShiftFlag = false;
        targetSongBank = activeSongBank;
        lcd_drawSongBankTab(activeSongBank, false);
    }

    // 4. TRANSPORT FLAG RESET
    // Put transport into fully stopped state.
    stopFlag = false;
    resetFlag = false;
    playActive = false;
    recordActive = false;
    io.midi.txStartPending = false;
    io.sync.txPulseCounter = 0;
    io.sync.txTrsTickCounter = 0;
    if (io.syncOut == 2) {
        HAL_GPIO_WritePin(SYNC_OUT_GATE_GPIO_Port, SYNC_OUT_GATE_Pin, GPIO_PIN_RESET);
    }

    // 5. ICON STATE UPDATE
    // Update transport icons to reflect stopped mode.
    resetIcon.flag = true;
    resetIcon.mode = false;
    playIcon.flag = true;
    playIcon.mode = false;
    stopIcon.flag = true;
    stopIcon.mode = true;
    recordIcon.flag = true;
    recordIcon.mode = false;

    // 6. PLAY POINTER RECALCULATION
    // Recompute play beat pointers for all layers after transport stop.
    for (uint8_t i = 0; i < kLayerLibrarySize; i++) {
        layerSong_calculatePlayBeatNum(i, activeSongBank, playInterval);
    }
}

void Controller::reset() {
    /// @brief Resets transport to loop start and normalizes related runtime states.

    // 1. MIDI RESET TRANSMISSION
    // Enqueue MIDI Stop (0xFC) + Song Position Pointer to 0 (0xF2 0x00 0x00)
    // to signal all connected devices to rewind to position 1.
    if (io.midi.txTransport) {
        if (!resetFlag) {
            static const uint8_t kMidiTrigResetSysEx[5] = {
                kMidiSysExStart,
                kMidiSysExManufacturerNonCommercial,
                kMidiSysExTransportFamily,
                kMidiSysExTrigReset,
                kMidiSysExEnd};
            enqueueMidiTx(kMidiTrigResetSysEx, 5);
        }

        static const uint8_t kMidiStop = 0xFC;
        static const uint8_t kMidiSpp[3] = {0xF2, 0x00, 0x00};
        enqueueMidiTx(&kMidiStop, 1);
        enqueueMidiTx(kMidiSpp, 3);
    }

    // 3. RESET CONDITION VALIDATION
    // Continue only when play head moved or precount is active.
    if ((playInterval != 0) || (metronome.precountState)) {
        // 3. PRECOUNT STATE RESET
        // Clear metronome precount counters and hide countdown UI.
        if (metronome.precountState) {
            metronome.precountState = false;
            metronome.precounter = 0;
            metronome.countDownFlag = false;
            metronome.countDown = 0;
            lcd_clearCountDown();
        }

        // 4. BANK SHIFT CANCEL
        // Cancel pending bank shift and restore active bank indicator.
        if (bankShiftFlag) {
            bankShiftFlag = false;
            targetSongBank = activeSongBank;
            lcd_drawSongBankTab(activeSongBank, false);
        }

        // 5. TRANSPORT FLAG RESET
        // Put transport into non-running state and clear trigger flags.
        stopFlag = false;
        resetFlag = false;
        playActive = false;
        recordActive = false;
        io.midi.txStartPending = false;

        // 6. ICON STATE UPDATE
        // Update transport icons to reflect reset mode.
        resetIcon.flag = true;
        resetIcon.mode = true;
        playIcon.flag = true;
        playIcon.mode = false;
        stopIcon.flag = true;
        stopIcon.mode = false;
        recordIcon.flag = true;
        recordIcon.mode = false;

        // 7. PLAYHEAD RESET
        // Reset play interval and arm restart logic for next cycle.
        playInterval = 0;
        resetPlayFlag = true;
        io.sync.txPulseCounter = 0;
        io.sync.txTrsTickCounter = 0;
        if (io.syncOut == 2) {
            HAL_GPIO_WritePin(SYNC_OUT_GATE_GPIO_Port, SYNC_OUT_GATE_Pin, GPIO_PIN_RESET);
        }

        // 8. PLAY POINTER RECALCULATION
        // Recompute play beat pointers for all layers at loop start.
        for (uint8_t i = 0; i < kLayerLibrarySize; i++) {
            layerSong_calculatePlayBeatNum(i, activeSongBank, playInterval);
        }

        // 9. LFO RESET TO PHASE START
        // Reset each LFO counter to its configured phase-start sample.
        for (uint8_t j = 0; j < kLfoLibrarySize; j++) {
            lfoLibrary[j].sampleCounter = lfoLibrary[j].sampleStart;
        }
    }
}

void Controller::triggerStop() {
    /// @brief Arms stop at musical boundary or stops immediately during precount.

    if (io.midi.txTransport) {
        static const uint8_t kMidiTrigStopSysEx[5] = {
            kMidiSysExStart,
            kMidiSysExManufacturerNonCommercial,
            kMidiSysExTransportFamily,
            kMidiSysExTrigStop,
            kMidiSysExEnd};
        enqueueMidiTx(kMidiTrigStopSysEx, 5);
    }

    // 1. TRIGGER RESOLUTION
    // Stop immediately in precount; otherwise arm stop trigger interval.
    if (metronome.precountState) {
        stop();
    } else {
        stopFlag = true;
        resetFlag = false;
        stopInterval = calculateTriggerInterval();
        resetIcon.flag = true;
        resetIcon.mode = false;

        // stopIcon.flag = true;
        // stopIcon.mode = true;
    }
}

void Controller::triggerReset() {
    /// @brief Arms reset at musical boundary or resets immediately during precount.

    if (io.midi.txTransport) {
        static const uint8_t kMidiTrigResetSysEx[5] = {
            kMidiSysExStart,
            kMidiSysExManufacturerNonCommercial,
            kMidiSysExTransportFamily,
            kMidiSysExTrigReset,
            kMidiSysExEnd};
        enqueueMidiTx(kMidiTrigResetSysEx, 5);
    }

    // 1. TRIGGER RESOLUTION
    // Reset immediately in precount; otherwise arm reset trigger interval.
    if (metronome.precountState) {
        reset();
    } else {
        stopFlag = false;
        resetFlag = true;
        resetInterval = calculateTriggerInterval();

        // resetIcon.flag = true;
        // resetIcon.mode = true;
        stopIcon.flag = true;
        stopIcon.mode = false;
    }
}

////////////////////////////////////////////////////////////////////////////////
/* Audio Functions -----------------------------------------------------------*/
////////////////////////////////////////////////////////////////////////////////

void Controller::processAudioBlock(uint32_t* inputBuffer_, uint32_t* outputBuffer_) {
    /// @brief Orchestrates the complete real-time audio processing pipeline, managing signal generation, sequential DSP stages, and final output buffering.

    // 0. I2S ERROR FLAG POLL
    // Count and clear overrun/underrun. The HAL never enables these interrupts, so polling
    // here is the only visibility; an rx overrun can permanently shift I2S word alignment.
    uint32_t i2sStatus = SPI3->SR;
    if (i2sStatus & SPI_SR_OVR) {
        i2sOvrCount++;
        SPI3->IFCR = SPI_IFCR_OVRC;
    }
    if (i2sStatus & SPI_SR_UDR) {
        i2sUdrCount++;
        SPI3->IFCR = SPI_IFCR_UDRC;
    }

    // 1. SYSTEM READINESS CHECK
    // Bypass processing during initialization menu to prevent audio artifacts.
    if (menu != INIT_MENU) {
        // 2. SIGNAL GENERATION & INPUT ACQUISITION
        // Acquire line-in, metronome, and layer source buffers.
        processAudioReceive(inputBuffer_);

        // Generate internal metronome click signal.
        processAudioMetronome();

        // Process active layer sample playback.
        processAudioLayer();

        // 3. SERIAL DSP CHAIN
        // Run EQ, Filter, Effect, and Reverb stages in order.
        processAudioEq();

        // Dual-bus filtering stage.
        processAudioFilter();

        // Dual-bus effect stage.
        processAudioEffect();

        // Global reverb stage.
        processAudioReverb();

        // 4. FINAL OUTPUT PROCESSING
        // Apply final mix and write to I2S output buffer.
        processAudioSend(outputBuffer_);
    }
}

// Scale applied to the summed L+R input. 2^-32 maps a full-scale ADC pair to 1.0, which is
// the natural mapping and costs nothing in SNR - it undoes an attenuation rather than adding
// gain. The gate thresholds in Global.h are referenced to the signal after this scale, so
// changing it means scaling them by the same factor.
//   4.65661287e-10f = 2^-31, +6 dB          2.32830644e-10f = 2^-32, unity
//   1.16415322e-10f = 2^-33, the original >> 2 behaviour
#define LINE_IN_INPUT_SCALE 2.32830644e-10f

#define LINE_IN_LPF_COEF 0.643923f
#define LINE_IN_LPF_ENABLE 1   // 0: bypass stage 1 (lpf), 1: one-pole (light), 2: two-pole cascade (original, steeper)
#define LINE_IN_GATE_ENABLE 1  // 0: bypass stage 2 (noise gate), 1: normal operation

void Controller::processAudioReceive(uint32_t* inputBuffer_) {
    static float dcX1 = 0, dcY1 = 0;              // dc blocker state
    static float lpfState1 = 0, lpfState2 = 0;    // low-pass state (stage 2 used only at LINE_IN_LPF_ENABLE == 2)
    static float env = 0.0f, gateGain = 0.0f;     // expander state
    static uint32_t holdCounter = 0;

    if (mixer.liMute) {
        // Clear the filter and expander state too. Leaving it stale means the next enable
        // rings the dc blocker and can start with the expander already open.
        memset(audioReceive, 0, I2S_BLOCK_SIZE * sizeof(float));
        dcX1 = 0.0f;
        dcY1 = 0.0f;
        lpfState1 = 0.0f;
        lpfState2 = 0.0f;
        env = 0.0f;
        gateGain = 0.0f;
        holdCounter = 0;
        return;
    }
    const float currentVol = mixer.masterVolumeFloat * kMixerLiVolumeDataLibrary[mixer.liVolume].data;
    for (uint16_t i = 0; i < I2S_BLOCK_SIZE; i++) {
        int32_t rawL = static_cast<int32_t>(inputBuffer_[i * 2]);
        int32_t rawR = static_cast<int32_t>(inputBuffer_[i * 2 + 1]);
        float rawSignal = (static_cast<float>(rawL) + static_cast<float>(rawR)) * LINE_IN_INPUT_SCALE;

        // stage 0: dc blocker (high-pass filter at ~5hz)
        float signal = rawSignal - dcX1 + (0.995f * dcY1);
        dcX1 = rawSignal;
        dcY1 = signal;

        // stage 1: low-pass (0: bypass, 1: one-pole light, 2: two-pole cascade)
#if LINE_IN_LPF_ENABLE == 1
        lpfState1 += LINE_IN_LPF_COEF * (signal - lpfState1);
        signal = lpfState1;
#elif LINE_IN_LPF_ENABLE == 2
        lpfState1 += LINE_IN_LPF_COEF * (signal - lpfState1);
        lpfState2 += LINE_IN_LPF_COEF * (lpfState1 - lpfState2);
        signal = lpfState2;
#endif

        // stage 2: downward expander
#if LINE_IN_GATE_ENABLE
        float absSig = fabsf(signal);
        env = (absSig > env) ? (env * 0.95f + absSig * 0.05f) : (env * 0.9995f + absSig * 0.0005f);
        // hold keeps the target pinned open briefly after a transient
        if (env > LINE_IN_GATE_THRESH_OPEN) {
            holdCounter = LINE_IN_GATE_HOLD_SAMPLES;
        } else if (holdCounter > 0) {
            holdCounter--;
        }
        // target gain: proportional between the thresholds, pinned at the floor below close
        float target;
        if (holdCounter > 0 || env >= LINE_IN_GATE_THRESH_OPEN) {
            target = 1.0f;
        } else if (env <= LINE_IN_GATE_THRESH_CLOSE) {
            target = LINE_IN_GATE_FLOOR_GAIN;
        } else {
            float frac = (env - LINE_IN_GATE_THRESH_CLOSE) / (LINE_IN_GATE_THRESH_OPEN - LINE_IN_GATE_THRESH_CLOSE);
            target = LINE_IN_GATE_FLOOR_GAIN + (1.0f - LINE_IN_GATE_FLOOR_GAIN) * frac;
        }
        // rising is fast and linear; falling eases toward the target exponentially
        if (target > gateGain) {
            gateGain = fminf(target, gateGain + LINE_IN_GATE_ATTACK);
        } else {
            gateGain += (target - gateGain) * (1.0f - LINE_IN_GATE_RELEASE_COEF);
        }
#else
        gateGain = 1.0f;
#endif

        float out = signal * gateGain * currentVol;
        audioReceive[i] = clamp(out, -1.0f, 1.0f);
    }
}

void Controller::processAudioMetronome() {
    /// @brief Generates metronome click audio by fetching PCM data from a library, normalizing it to float, and managing playback state and sample indexing.

    // 1. BUFFER RESET & ACTIVITY CHECK
    // Clear metronome buffer and early-exit when inactive.
    memset(audioMetronome, 0, I2S_BLOCK_SIZE * sizeof(float));

    // Metronome inactive: skip block processing.
    if (!metroPlayData.active) return;
    // 2. SAMPLE LOOP PROCESSING
    // Fetch PCM data, normalize to float, and mix into output buffer.
    for (uint16_t i = 0; i < I2S_BLOCK_SIZE; i++) {
        // --- PCM Data Acquisition and Normalization ---
        // Fetch raw 16-bit PCM data from the metronome library based on measure type
        int16_t data16Bit = (int16_t)kMetronomeDataLibrary[metroPlayData.sample][metroPlayData.barMeasure][metroPlayData.counter];

        // Convert 16-bit integer to float range [-1.0, 1.0] and apply volume multiplier
        float dataFloat = (float)data16Bit * NORMALIZE_FACTOR_16BIT;
        float sample = dataFloat * metroPlayData.volumeMultiplier;

        // Mix the processed sample into the local metronome buffer
        audioMetronome[i] += sample;

        // --- Playback State Management ---
        // Advance sample index and stop when end of click sample is reached.
        if (metroPlayData.counter < metroPlayData.counterMax) {
            metroPlayData.counter++;
        } else {
            // End of sample reached: Reset counter and deactivate metronome trigger
            metroPlayData.counter = 0;
            metroPlayData.active = false;

            // Terminate processing for the remainder of the block to save CPU cycles
            break;
        }
    }
}

void Controller::processAudioLayer() {
    /// @brief Manages real-time audio playback for all layers, featuring sample retriggering, bitcrushing, linear interpolation, and multiple playback direction modes.

    // 1. CONSTANT INITIALIZATION
    // Prepare constants for 24-bit conversion and bit-depth operations.
    const float kScale24 = 16777215.0f;
    const float kInvScale24 = 1.0f / 16777215.0f;

    // 2. LAYER ITERATION
    // Process playback pipeline for each layer independently.
    for (uint8_t i = 0; i < kLayerLibrarySize; i++) {
        LayerPlayData& lD = layerPlayData[i];
        BeatPlayData& tBD = lD.tempBeatPlayData;
        BeatPlayData& aBD = lD.activeBeatPlayData;

        // Reset the audio buffer for the current layer
        memset(audioLayer[i], 0, I2S_BLOCK_SIZE * sizeof(float));

        // --- Handle Sample Retriggering ---
        if (aBD.newBeatFlag) {
            if (aBD.counterFade >= 49 || !aBD.active) {
                aBD.newBeatFlag = false;
                lD.beatStartFlag = true;
                lD.beatEndFlag = false;

                // Transfer temporary beat data to the active state
                memcpy(&aBD, &lD.tempBeatPlayData, sizeof(BeatPlayData));
                memset(&lD.tempBeatPlayData, 0x00, sizeof(BeatPlayData));

                // Deactivate layer if necessary and trigger MIDI Note Off
                if (!aBD.active) {
                    io.midi.txTriggerNoteOff[i] = true;
                    continue;
                }
            }
        }

        // Skip processing if the layer is inactive
        if (!aBD.active) continue;

        float* targetBuffer = audioLayer[i];

        // 3. PROCESSING PATH RESOLUTION
        // Use fast path for unity pitch + forward direction; else use interpolated slow path.
        bool isFastPath = (aBD.increment == 1.0f) && (aBD.directionMode == 0);

        if (isFastPath) {
            // --- Optimized Fast Path Processing ---
            uint32_t remainder = (uint32_t)(aBD.counterEnd - aBD.counter);
            uint16_t copySize = (remainder > I2S_BLOCK_SIZE) ? I2S_BLOCK_SIZE : (uint16_t)remainder;
            float* sourceAddress = (float*)(aBD.ramAddress + ((uint32_t)aBD.counter * 4));

            // Cache RAM data into local stack buffer for processing
            float localCache[I2S_BLOCK_SIZE];
            if (copySize > 0) memcpy(localCache, sourceAddress, copySize * sizeof(float));

            if (aBD.counter == aBD.counterStart) io.midi.txTriggerNoteOn[i] = true;

            bool bitCrushActive = (aBD.resolutionCoef != 0x00FFFFFF);

            for (uint16_t j = 0; j < copySize; j++) {
                float sample = localCache[j];

                // Apply Bitcrush effect if the resolution coefficient is modified
                if (bitCrushActive) {
                    float valShifted = (sample + 1.0f) * 0.5f;
                    uint32_t tempUnsigned = (uint32_t)(valShifted * kScale24);
                    tempUnsigned &= aBD.resolutionCoef;
                    float valBack = (float)tempUnsigned * kInvScale24;
                    sample = (valBack * 2.0f) - 1.0f;
                }

                // Handle fade-in/fade-out logic
                if ((aBD.newBeatFlag) && (!aBD.fadeAction)) aBD.fadeAction = true;
                if ((!aBD.fadeAction) && (aBD.fadeFlag) && ((aBD.counter + j) >= aBD.counterFadeStart)) {
                    aBD.fadeAction = true;
                }

                if (aBD.fadeAction) {
                    sample *= kFadeVolumeMultiplier[aBD.counterFade];
                    if (aBD.counterFade < 49) aBD.counterFade++;
                }

                // Apply final volume and store in output buffer
                targetBuffer[j] = sample * aBD.volumeMultiplier;
            }

            // Update sample counter and check for playback end
            aBD.counter += (float)copySize;
            if (copySize < I2S_BLOCK_SIZE) {
                lD.beatStartFlag = false;
                lD.beatEndFlag = true;
                aBD.active = false;
                aBD.counter = 0.0f;
                io.midi.txTriggerNoteOff[i] = true;
            }
        } else {
            // 4. SLOW PATH PROCESSING
            // Handle interpolated read and multi-direction playback modes.
            for (uint16_t k = 0; k < I2S_BLOCK_SIZE; k++) {
                bool endFlag = false;

                // Perform Linear Interpolation for pitch shifting
                float counterFloat = aBD.counter;
                uint32_t counterInt = (uint32_t)counterFloat;
                float counterDiff = counterFloat - (float)counterInt;
                uint32_t ramAddress = aBD.ramAddress + (counterInt * 4);

                // Helper lambda for reading RAM with integrated bitcrushing
                auto getSample = [&](uint32_t addr) -> float {
                    float val = *(volatile float*)addr;
                    if (aBD.resolutionCoef != 0x00FFFFFF) {
                        float valShifted = (val + 1.0f) * 0.5f;
                        uint32_t tempUnsigned = (uint32_t)(valShifted * kScale24);
                        tempUnsigned &= aBD.resolutionCoef;
                        float valBack = (float)tempUnsigned * kInvScale24;
                        val = (valBack * 2.0f) - 1.0f;
                    }
                    return val;
                };

                float currentSample;
                if (counterDiff == 0.0f) {
                    currentSample = getSample(ramAddress);
                } else {
                    // Linear interpolation between two samples
                    currentSample = getSample(ramAddress) + ((getSample(ramAddress + 4) - getSample(ramAddress)) * counterDiff);
                }

                // Handle Fading Triggers
                if ((aBD.newBeatFlag) && (!aBD.fadeAction)) aBD.fadeAction = true;
                if (!aBD.fadeAction) {
                    bool fadeTrigger = (aBD.directionMode == 0) ? (aBD.fadeFlag && aBD.counter >= aBD.counterFadeStart) : (aBD.fadeFlag && aBD.counter <= aBD.counterFadeStart);
                    if (fadeTrigger) aBD.fadeAction = true;
                }

                if (aBD.fadeAction) {
                    currentSample *= kFadeVolumeMultiplier[aBD.counterFade];
                    if (aBD.counterFade < 49)
                        aBD.counterFade++;
                    else if (!aBD.newBeatFlag)
                        endFlag = true;
                }

                // Store sample with volume scaling
                targetBuffer[k] = currentSample * aBD.volumeMultiplier;

                // --- Direction and Counter Management ---
                switch (aBD.directionMode) {
                    case 0:  // Forward playback
                        if (aBD.counter == aBD.counterStart) io.midi.txTriggerNoteOn[i] = true;
                        aBD.counter += aBD.increment;
                        if (aBD.counter > (aBD.counterEnd - 1.0f)) endFlag = true;
                        break;

                    case 1:  // Backward playback
                        if (aBD.counter == aBD.counterEnd - 1.0f) io.midi.txTriggerNoteOn[i] = true;
                        aBD.counter -= aBD.increment;
                        if (aBD.counter < aBD.counterStart) endFlag = true;
                        break;

                    case 2:  // Ping (Forward then Backward)
                        switch (aBD.directionPhase) {
                            case 0:  // Forward phase
                                if (aBD.counter == 0.0f) io.midi.txTriggerNoteOn[i] = true;
                                aBD.counter += aBD.increment;
                                if (aBD.counter > (aBD.counterEnd - 1.0f)) {
                                    aBD.counter = aBD.counterEnd - 1.0f;
                                    aBD.directionPhase = 1;
                                    aBD.fadeFlag = true;
                                }
                                break;

                            case 1:  // Backward phase
                                aBD.counter -= aBD.increment;
                                if (aBD.counter < aBD.counterStart) endFlag = true;
                                break;
                        }
                        break;

                    case 3:  // Pong (Backward then Forward)
                        switch (aBD.directionPhase) {
                            case 0:  // Backward phase
                                if (aBD.counter == aBD.counterEnd - 1.0f) io.midi.txTriggerNoteOn[i] = true;
                                aBD.counter -= aBD.increment;
                                if (aBD.counter < aBD.counterStart) {
                                    aBD.counter = 0.0f;
                                    aBD.directionPhase = 1;
                                    aBD.fadeFlag = true;
                                }
                                break;

                            case 1:  // Forward phase
                                aBD.counter += aBD.increment;
                                if (aBD.counter > (aBD.counterEnd - 1.0f)) endFlag = true;
                                break;
                        }
                        break;
                }

                // 5. END-OF-SAMPLE HANDLING
                // Finalize beat state and emit MIDI Note Off on playback end.
                if (endFlag) {
                    lD.beatStartFlag = false;
                    lD.beatEndFlag = true;
                    aBD.active = false;
                    aBD.counter = 0.0f;
                    io.midi.txTriggerNoteOff[i] = true;
                    break;
                }
            }
        }
    }
}

void Controller::processAudioEq() {
    /// @brief Accumulates multi-source audio and processes it through a sequential 6-band parametric EQ chain including Low Shelf, High Shelf, and four Peak filters.

    // 1. EQ BUS RESET
    // Clear EQ accumulation buffer for current block.
    memset(audioEq, 0, I2S_BLOCK_SIZE * sizeof(float));

    // 2. INPUT ACCUMULATION
    // Accumulate line-in, metronome, and layer signals routed to EQ bus.
    if (mixer.liMixerInMode == MIXER_IN_EQ) {
        for (uint16_t i = 0; i < I2S_BLOCK_SIZE; i++) {
            audioEq[i] += audioReceive[i];
        }
    }

    // Accumulate metronome signal
    if (metroPlayData.mixerInMode == MIXER_IN_EQ) {
        for (uint16_t i = 0; i < I2S_BLOCK_SIZE; i++) {
            audioEq[i] += audioMetronome[i];
        }
    }

    // Accumulate all active layer signals
    for (uint8_t i = 0; i < kLayerLibrarySize; i++) {
        if (layerPlayData[i].activeBeatPlayData.mixerInMode == MIXER_IN_EQ) {
            for (uint16_t k = 0; k < I2S_BLOCK_SIZE; k++) {
                audioEq[k] += audioLayer[i][k];
            }
        }
    }

    // 3. BYPASS CHECK
    // Early return when EQ and EQ transition engines are inactive.
    if (!eq.active && !eq.genTransition.active) return;

    // 4. ACTIVE BAND RESOLUTION
    // Mark active bands where gain differs from zero.
    bool activeLS = (eq.gainLowShelf != kEqGainZero);
    bool activeHS = (eq.gainHighShelf != kEqGainZero);
    bool activeP0 = (eq.gainPeak[0] != kEqGainZero);
    bool activeP1 = (eq.gainPeak[1] != kEqGainZero);
    bool activeP2 = (eq.gainPeak[2] != kEqGainZero);
    bool activeP3 = (eq.gainPeak[3] != kEqGainZero);

    // 5. BIQUAD CHAIN PROCESSING
    // Process sample-by-sample through enabled EQ stages.
    for (uint16_t i = 0; i < I2S_BLOCK_SIZE; i++) {
        float input = audioEq[i];
        float processed = input;

        // Apply sequential biquad filters (Direct Form calculation)
        processed = processEqBiquad(eq.filterLowShelf, processed, activeLS);
        processed = processEqBiquad(eq.filterHighShelf, processed, activeHS);
        processed = processEqBiquad(eq.filterPeak[0], processed, activeP0);
        processed = processEqBiquad(eq.filterPeak[1], processed, activeP1);
        processed = processEqBiquad(eq.filterPeak[2], processed, activeP2);
        processed = processEqBiquad(eq.filterPeak[3], processed, activeP3);

        // Handle final output with wet/dry transition support
        if (eq.genTransition.active) {
            audioEq[i] = (processed * eq.genTransition.activeWet) + (input * eq.genTransition.activeDry);
        } else {
            audioEq[i] = processed;
        }
    }
}

void Controller::processAudioFilter() {
    /// @brief Accumulates audio from EQ, Line-in, Metronome, and Layers into two filter buses and processes them serially through biquad filter engines.

    // 1. FILTER BUS RESET
    // Clear both filter buses before accumulation.
    memset(audioFilter[0], 0, I2S_BLOCK_SIZE * sizeof(float));
    memset(audioFilter[1], 0, I2S_BLOCK_SIZE * sizeof(float));

    // 2. INPUT ACCUMULATION
    // Route EQ, line-in, metronome, and layer signals into filter buses.
    for (uint16_t i = 0; i < I2S_BLOCK_SIZE; i++) {
        audioFilter[0][i] += audioEq[i];
    }

    // Accumulate line-in signal based on routing mode
    if (mixer.liMixerInMode == MIXER_IN_FILTER_0) {
        for (uint16_t i = 0; i < I2S_BLOCK_SIZE; i++) audioFilter[0][i] += audioReceive[i];
    } else if (mixer.liMixerInMode == MIXER_IN_FILTER_1) {
        for (uint16_t i = 0; i < I2S_BLOCK_SIZE; i++) audioFilter[1][i] += audioReceive[i];
    }

    // Accumulate metronome signal if active
    if (metroPlayData.active) {
        if (metroPlayData.mixerInMode == MIXER_IN_FILTER_0) {
            for (uint16_t i = 0; i < I2S_BLOCK_SIZE; i++) audioFilter[0][i] += audioMetronome[i];
        } else if (metroPlayData.mixerInMode == MIXER_IN_FILTER_1) {
            for (uint16_t i = 0; i < I2S_BLOCK_SIZE; i++) audioFilter[1][i] += audioMetronome[i];
        }
    }

    // Accumulate all active layer signals based on their routing
    for (uint8_t i = 0; i < kLayerLibrarySize; i++) {
        MixerInMode mode = (MixerInMode)layerPlayData[i].activeBeatPlayData.mixerInMode;
        if (mode == MIXER_IN_FILTER_0) {
            for (int j = 0; j < I2S_BLOCK_SIZE; j++) audioFilter[0][j] += audioLayer[i][j];
        } else if (mode == MIXER_IN_FILTER_1) {
            for (int j = 0; j < I2S_BLOCK_SIZE; j++) audioFilter[1][j] += audioLayer[i][j];
        }
    }

    // 3. FILTER ENGINE 0 PROCESSING
    // Process bus-0 through filter-0 and feed result into bus-1.
    if ((filter[0].active) || (filter[0].genTransition.active)) {
        for (uint16_t i = 0; i < I2S_BLOCK_SIZE; i++) {
            float audio = audioFilter[0][i];
            audio = processAudioFilterHelper(0, audio);
            audioFilter[0][i] = audio;
            audioFilter[1][i] += audio;  // Accumulate processed output into Bus 1
        }
    } else {
        // Bypass: Filter 0 is inactive, sum raw Bus 0 signal into Bus 1
        for (uint16_t i = 0; i < I2S_BLOCK_SIZE; i++) {
            audioFilter[1][i] += audioFilter[0][i];
        }
    }

    // 4. FILTER ENGINE 1 PROCESSING
    // Process bus-1 through filter-1 before next stage.
    if ((filter[1].active) || (filter[1].genTransition.active)) {
        for (uint16_t i = 0; i < I2S_BLOCK_SIZE; i++) {
            float audio = audioFilter[1][i];
            audio = processAudioFilterHelper(1, audio);
            audioFilter[1][i] = audio;
        }
    }
}

void Controller::processAudioEffect() {
    /// @brief Accumulates audio sources into two parallel effect buses and processes them serially through internal effect engines with transition support.

    // 1. EFFECT BUS RESET
    // Clear both effect buses before accumulation.
    memset(audioEffect[0], 0, I2S_BLOCK_SIZE * sizeof(float));
    memset(audioEffect[1], 0, I2S_BLOCK_SIZE * sizeof(float));

    // 2. INPUT ACCUMULATION
    // Route filter output, line-in, metronome, and layer signals into effect buses.
    for (uint16_t i = 0; i < I2S_BLOCK_SIZE; i++) {
        audioEffect[0][i] += audioFilter[1][i];
    }

    // Accumulate line-in based on routing mode
    if (mixer.liMixerInMode == MIXER_IN_EFFECT_0) {
        for (uint16_t i = 0; i < I2S_BLOCK_SIZE; i++) audioEffect[0][i] += audioReceive[i];
    } else if (mixer.liMixerInMode == MIXER_IN_EFFECT_1) {
        for (uint16_t i = 0; i < I2S_BLOCK_SIZE; i++) audioEffect[1][i] += audioReceive[i];
    }

    // Accumulate metronome signal if active
    if (metroPlayData.active) {
        if (metroPlayData.mixerInMode == MIXER_IN_EFFECT_0) {
            for (uint16_t i = 0; i < I2S_BLOCK_SIZE; i++) audioEffect[0][i] += audioMetronome[i];
        } else if (metroPlayData.mixerInMode == MIXER_IN_EFFECT_1) {
            for (uint16_t i = 0; i < I2S_BLOCK_SIZE; i++) audioEffect[1][i] += audioMetronome[i];
        }
    }

    // Accumulate all active layer signals based on their routing
    for (uint8_t i = 0; i < kLayerLibrarySize; i++) {
        MixerInMode mode = (MixerInMode)layerPlayData[i].activeBeatPlayData.mixerInMode;
        if (mode == MIXER_IN_EFFECT_0) {
            for (int j = 0; j < I2S_BLOCK_SIZE; j++) audioEffect[0][j] += audioLayer[i][j];
        } else if (mode == MIXER_IN_EFFECT_1) {
            for (int j = 0; j < I2S_BLOCK_SIZE; j++) audioEffect[1][j] += audioLayer[i][j];
        }
    }

    // 3. EFFECT ENGINE 0 PROCESSING
    // Process bus-0 through effect-0 and feed result into bus-1.
    if ((effect[0].active) || (effect[0].genTransition.active)) {
        for (uint16_t i = 0; i < I2S_BLOCK_SIZE; i++) {
            float audio = audioEffect[0][i];
            audio = processAudioEffectHelper(0, audio);
            audioEffect[0][i] = audio;
            audioEffect[1][i] += audio;  // Send processed output to Bus 1
        }
    } else {
        // Bypass: Effect 0 is inactive, sum raw Bus 0 signal into Bus 1
        for (uint16_t i = 0; i < I2S_BLOCK_SIZE; i++) {
            audioEffect[1][i] += audioEffect[0][i];
        }
    }

    // 4. EFFECT ENGINE 1 PROCESSING
    // Process bus-1 through effect-1 before reverb stage.
    if ((effect[1].active) || (effect[1].genTransition.active)) {
        for (uint16_t i = 0; i < I2S_BLOCK_SIZE; i++) {
            float audio = audioEffect[1][i];
            audio = processAudioEffectHelper(1, audio);
            audioEffect[1][i] = audio;
        }
    }
}

void Controller::processAudioReverb() {
    /// @brief Accumulates inputs and applies a damped stereo reverb with pre-delay and surround enhancement.

    // 1. REVERB BUS RESET
    // Clear stereo reverb accumulation buffers for current block.
    memset(audioReverb_L, 0, I2S_BLOCK_SIZE * sizeof(float));
    memset(audioReverb_R, 0, I2S_BLOCK_SIZE * sizeof(float));

    // 2. INPUT ACCUMULATION
    // Sum effect, line-in, metronome, and layer signals into left reverb input.
    for (uint16_t i = 0; i < I2S_BLOCK_SIZE; i++) {
        audioReverb_L[i] += audioEffect[1][i];
    }

    // Accumulate line-in
    if (mixer.liMixerInMode == MIXER_IN_REVERB) {
        for (uint16_t i = 0; i < I2S_BLOCK_SIZE; i++) audioReverb_L[i] += audioReceive[i];
    }

    // Accumulate metronome
    if (metroPlayData.active && metroPlayData.mixerInMode == MIXER_IN_REVERB) {
        for (uint16_t i = 0; i < I2S_BLOCK_SIZE; i++) audioReverb_L[i] += audioMetronome[i];
    }

    // Accumulate layers
    for (uint8_t i = 0; i < kLayerLibrarySize; i++) {
        if (layerPlayData[i].activeBeatPlayData.mixerInMode == MIXER_IN_REVERB) {
            for (uint16_t j = 0; j < I2S_BLOCK_SIZE; j++) audioReverb_L[j] += audioLayer[i][j];
        }
    }

    // 3. REVERB ENGINE PROCESSING
    // Run pre-delay, comb/all-pass, and surround output generation.
    if ((reverb.active) || (reverb.genTransition.active)) {
        // Cache parameters locally for faster access during the sample loop
        float cFB = reverb.combFeedback;
        float cD1 = reverb.combDecay1;
        float cD2 = reverb.combDecay2;
        float apFB = reverb.apassFeedback;

        // Pre-calculate scaler for comb filter inputs to prevent clipping
        const float kCombInputScale = 0.015f;

        for (uint16_t i = 0; i < I2S_BLOCK_SIZE; i++) {
            float inputSample = audioReverb_L[i];

            // Apply anti-denormal noise to prevent CPU spikes on low signals
            inputSample += REVERB_ANTI_DENORMAL;

            // 3.1 PRE-DELAY PROCESSING
            reverb.preDelayBuffer[reverb.preDelay_recordInterval] = inputSample;
            float reverbInput = reverb.preDelayBuffer[reverb.preDelay_playInterval];

            if (++reverb.preDelay_playInterval >= reverb.kPreDelayBufferSize) reverb.preDelay_playInterval = 0;
            if (++reverb.preDelay_recordInterval >= reverb.kPreDelayBufferSize) reverb.preDelay_recordInterval = 0;

            // 3.2 COMB FILTERS (Parallel)
            float inputComb = reverbInput * kCombInputScale;

            reverb.comb1Out = processReverbComb(reverb.comb1Buffer, reverb.comb1Index, reverb.comb1Size, reverb.comb1Filter, inputComb, cFB, cD1, cD2);
            reverb.comb2Out = processReverbComb(reverb.comb2Buffer, reverb.comb2Index, reverb.comb2Size, reverb.comb2Filter, inputComb, cFB, cD1, cD2);
            reverb.comb3Out = processReverbComb(reverb.comb3Buffer, reverb.comb3Index, reverb.comb3Size, reverb.comb3Filter, inputComb, cFB, cD1, cD2);
            reverb.comb4Out = processReverbComb(reverb.comb4Buffer, reverb.comb4Index, reverb.comb4Size, reverb.comb4Filter, inputComb, cFB, cD1, cD2);
            reverb.comb5Out = processReverbComb(reverb.comb5Buffer, reverb.comb5Index, reverb.comb5Size, reverb.comb5Filter, inputComb, cFB, cD1, cD2);
            reverb.comb6Out = processReverbComb(reverb.comb6Buffer, reverb.comb6Index, reverb.comb6Size, reverb.comb6Filter, inputComb, cFB, cD1, cD2);
            reverb.comb7Out = processReverbComb(reverb.comb7Buffer, reverb.comb7Index, reverb.comb7Size, reverb.comb7Filter, inputComb, cFB, cD1, cD2);
            reverb.comb8Out = processReverbComb(reverb.comb8Buffer, reverb.comb8Index, reverb.comb8Size, reverb.comb8Filter, inputComb, cFB, cD1, cD2);

            float combSum = reverb.comb1Out + reverb.comb2Out + reverb.comb3Out + reverb.comb4Out + reverb.comb5Out + reverb.comb6Out + reverb.comb7Out + reverb.comb8Out;

            // 3.3 ALL-PASS FILTERS (Serial Diffusion)
            reverb.apass1Out = processReverbAllpass(reverb.apass1Buffer, reverb.apass1Index, reverb.apass1Size, combSum, apFB);
            reverb.apass2Out = processReverbAllpass(reverb.apass2Buffer, reverb.apass2Index, reverb.apass2Size, reverb.apass1Out, apFB);
            reverb.apass3Out = processReverbAllpass(reverb.apass3Buffer, reverb.apass3Index, reverb.apass3Size, reverb.apass2Out, apFB);
            reverb.apass4Out = processReverbAllpass(reverb.apass4Buffer, reverb.apass4Index, reverb.apass4Size, reverb.apass3Out, apFB);

            float processedSignal = reverb.apass4Out;

            // 3.4 OUTPUT MIXING & SURROUND
            float finalReverb;
            float outL, outR;

            // Apply manual wet/dry mix
            float mixedSignal = (processedSignal * reverb.wetFloat) + (inputSample * reverb.dryFloat);

            // Handle Parameter Transitions
            if (reverb.genTransition.active) {
                finalReverb = (mixedSignal * reverb.genTransition.activeWet) + (inputSample * reverb.genTransition.activeDry);
                reverb.surroundBuffer[reverb.surround_recordInterval] = finalReverb;

                if ((reverb.genTransition.mode == REV_MODE_ACTIVE) || (reverb.genTransition.mode == REV_MODE_SURROUND)) {
                    outL = finalReverb;
                    outR = (reverb.surroundBuffer[reverb.surround_playInterval] * reverb.genTransition.activeWet) + (finalReverb * reverb.genTransition.activeDry);
                } else {
                    outL = finalReverb;
                    outR = reverb.surroundBuffer[reverb.surround_playInterval];
                }
            } else {
                finalReverb = mixedSignal;
                reverb.surroundBuffer[reverb.surround_recordInterval] = finalReverb;
                outL = finalReverb;
                outR = reverb.surroundBuffer[reverb.surround_playInterval];
            }

            // Update surround circular buffer indices
            if (++reverb.surround_playInterval >= reverb.kSurroundBufferSize) reverb.surround_playInterval = 0;
            if (++reverb.surround_recordInterval >= reverb.kSurroundBufferSize) reverb.surround_recordInterval = 0;

            // Final block output write
            audioReverb_L[i] = outL;
            audioReverb_R[i] = outR;
        }
    } else {
        // Bypass mode: Effect is inactive, copy mono accumulation to stereo output
        memcpy(audioReverb_R, audioReverb_L, I2S_BLOCK_SIZE * sizeof(float));
    }
}

void Controller::processAudioSend(uint32_t* outputBuffer) {
    /// @brief Accumulates all audio sources, applies master volume and LPF, and performs final output processing including soft clipping and peak detection.

    // 1. SEND BUS ACCUMULATION
    // Merge reverb output with routed line-in, metronome, and layer signals.
    memcpy(audioSend_L, audioReverb_L, I2S_BLOCK_SIZE * sizeof(float));
    memcpy(audioSend_R, audioReverb_R, I2S_BLOCK_SIZE * sizeof(float));

    // Accumulate line-in signal
    if (mixer.liMixerInMode == MIXER_IN_SEND) {
        for (uint16_t i = 0; i < I2S_BLOCK_SIZE; i++) {
            audioSend_L[i] += audioReceive[i];
            audioSend_R[i] += audioReceive[i];
        }
    }

    // Accumulate metronome signal
    if (metroPlayData.active && metroPlayData.mixerInMode == MIXER_IN_SEND) {
        for (uint16_t i = 0; i < I2S_BLOCK_SIZE; i++) {
            audioSend_L[i] += audioMetronome[i];
            audioSend_R[i] += audioMetronome[i];
        }
    }

    // Accumulate all active layer signals
    for (uint8_t i = 0; i < kLayerLibrarySize; i++) {
        if (layerPlayData[i].activeBeatPlayData.mixerInMode == MIXER_IN_SEND) {
            float* layerBuffer = audioLayer[i];
            for (uint16_t j = 0; j < I2S_BLOCK_SIZE; j++) {
                float audio = layerBuffer[j];
                audioSend_L[j] += audio;
                audioSend_R[j] += audio;
            }
        }
    }

    // 2. MASTER MUTE CHECK
    // Output silence and return when master mute is enabled.
    if (mixer.masterMute) {
        memset(outputBuffer, 0, I2S_BLOCK_SIZE * I2S_CHANNEL_COUNT * sizeof(uint32_t));
        return;
    }

    // 3. FINAL OUTPUT FORMATTING
    // Apply gain/LPF/peak/clipping and write interleaved I2S samples.
    for (uint16_t i = 0; i < I2S_BLOCK_SIZE; i++) {
        float outL = audioSend_L[i];
        float outR = audioSend_R[i];

        // Apply master volume gains
        outL *= mixer.volumeLeftFloat;
        outR *= mixer.volumeRightFloat;

        // Apply low-pass filters if active
        if (lpf[0].active) outL = processAudioLpfHelper(0, outL);
        if (lpf[1].active) outR = processAudioLpfHelper(1, outR);

        // Calculate and update peak levels
        float absAudioMax_L = fabsf(outL);
        float absAudioMax_R = fabsf(outR);
        if (absAudioMax_L > audioPeak_L) audioPeak_L = absAudioMax_L;
        if (absAudioMax_R > audioPeak_R) audioPeak_R = absAudioMax_R;

        // Apply soft knee clipping to prevent digital distortion
        outL = softKneeClip(outL);
        outR = softKneeClip(outR);

        // Convert float samples to 32-bit integers
        int32_t sampleL = static_cast<int32_t>(outL * INT32_MAX_FLOAT);
        int32_t sampleR = static_cast<int32_t>(outR * INT32_MAX_FLOAT);

        // Write final samples to the interleaved I2S output buffer
        outputBuffer[i * 2] = static_cast<uint32_t>(sampleL);
        outputBuffer[i * 2 + 1] = static_cast<uint32_t>(sampleR);
    }
}

float Controller::processAudioFilterHelper(uint8_t filterNum_, float audio_) {
    /// @brief Computes a biquad filter sample with input drive saturation, slope selection, and smooth parameter transitions.

    // 1. FILTER STATE RESOLUTION
    // Resolve filter reference and initialize local input/output values.

    Filter& filter_ = filter[filterNum_];
    float input = audio_;
    float output;

    if ((filter_.active) || (filter_.genTransition.active)) {
        // 2. INPUT DRIVE APPLY
        // Convert drive control to gain multiplier and apply optional soft clip.

        float driveGain = 1.0f + ((float)filter_.drive * 0.04f);
        input *= driveGain;

        // Optional: Soft-clip the driven input to keep it within a musical range
        if (filter_.drive > 0) {
            input = softKneeClip(input);
        }

        // 3. BIQUAD CALCULATION
        // Compute filtered sample with anti-denormal protection.

        float filteredSample = (filter_.b0 * input) + (filter_.b1 * filter_.x1) + (filter_.b2 * filter_.x2) - (filter_.a1 * filter_.y1) - (filter_.a2 * filter_.y2) + FILTER_ANTI_DENORMAL;

        // 4. FILTER HISTORY UPDATE
        // Shift input/output delay-line history buffers.

        filter_.x2 = filter_.x1;
        filter_.x1 = input;
        filter_.y2 = filter_.y1;
        filter_.y1 = filteredSample;

        // 5. SLOPE & MIX RESOLUTION
        // Resolve slope mode and wet/dry transition mix.

        float finalFilterOut;

        // Determine filter slope (0 = 6dB, 1 = 12dB)
        if (filter_.slope == 0) {
            finalFilterOut = (filteredSample * 0.5f) + (input * 0.5f);
        } else {
            finalFilterOut = filteredSample;
        }

        // Apply transition mix or standard wet/dry levels
        float wetLevel, dryLevel;
        if (filter_.genTransition.active) {
            wetLevel = filter_.genTransition.activeWet;
            dryLevel = filter_.genTransition.activeDry;
        } else {
            wetLevel = filter_.wetFloat;
            dryLevel = filter_.dryFloat;
        }

        // Generate final mixed output
        output = (finalFilterOut * wetLevel) + (audio_ * dryLevel);
    } else {
        // 6. BYPASS OUTPUT
        // Return original input when filter path is inactive.

        output = input;
    }

    return output;
}

float Controller::processAudioEffectHelper(uint8_t effectNum_, float audio_) {
    /// @brief Routes and processes audio through the selected effect engine.
    /// Supports Delay, Chorus, Flanger, Phaser, Dynamics (Comp/Exp), and Distortion (OD/Dist/Crush).

    Effect& effect_ = effect[effectNum_];
    float input = audio_;
    float output = 0.0f;

    // 1. EFFECT STATE VALIDATION
    // Process only when effect engine is active or in transition.

    if ((effect_.active) || (effect_.genTransition.active)) {
        // 2. EFFECT TYPE RESOLUTION
        // Resolve runtime type using transition override when active.
        uint8_t type = (effect_.genTransition.active) ? effect_.genTransition.activeType : effect_.type;
        switch (type) {
            case EF_DELAY: {
                // 1. SETUP & CACHING
                Delay& delay_ = effect_.delay;
                float* delayBuf = (float*)effect_.delayAddress;

                uint32_t pIdx = delay_.playInterval;
                uint32_t rIdx = delay_.recordInterval;
                const float kInv100 = 0.01f;

                // 2. SIGNAL PROCESSING
                // Read the delayed signal from the buffer
                float delayedSample = delayBuf[pIdx];

                // --- DAMPING FILTER (Feedback Loop) ---
                // This one-pole filter softens the repeats.
                float feedbackTarget = (input * delay_.level) + (delayedSample * delay_.feedback);
                float filteredFeedback = delay_.lastFeedbackSample + delay_.dampingAlpha * (feedbackTarget - delay_.lastFeedbackSample);

                // Update filter state for next sample
                delay_.lastFeedbackSample = filteredFeedback;

                // Anti-denormal for stability
                if (fabsf(filteredFeedback) < 1.0e-18f) filteredFeedback = 0.0f;

                // Write the filtered feedback back to the buffer
                delayBuf[rIdx] = filteredFeedback;

                // 3. OUTPUT MIXING
                // mixData represents the "Wet" signal (the delay repeats).
                // Using eDry and fWet for final balance.
                float dryLevel = (float)delay_.eDry * kInv100;
                float wetLevel = (float)delay_.fWet * kInv100;

                // Wet is the delayed sound, Dry is the pure input.
                float mixData = (delayedSample * wetLevel) + (input * dryLevel);

                // 4. TRANSITION & STORE
                if (effect_.genTransition.active) {
                    output = (mixData * effect_.genTransition.activeWet) + (input * effect_.genTransition.activeDry);
                } else {
                    output = mixData;
                }

                // 5. UPDATE INDICES
                // Advance pointers and wrap around circular buffer
                if (++pIdx >= kDelaySize) pIdx = 0;
                if (++rIdx >= kDelaySize) rIdx = 0;

                delay_.playInterval = pIdx;
                delay_.recordInterval = rIdx;
            } break;

            case EF_CHORUS: {
                Chorus& chorus_ = effect_.chorus;
                float* chorusBuffer = (float*)effect_.chorusAddress;  // Access circular buffer

                const float bufSizeFloat = (float)kChorusBufferSize;
                const int32_t bufSizeInt = (int32_t)kChorusBufferSize;
                const float kInv100 = 0.01f;

                uint32_t recIdx = chorus_.recordInterval;
                float dataChorusAccum = 0.0f;

                // 1. DUAL VOICE PROCESSING LOOP
                // We process two independent delay taps modulated by triangle LFOs.
                for (uint8_t i = 0; i < 2; i++) {
                    ChorusDelay& cD = chorus_.chorusDelay[i];

                    // --- LFO Management ---
                    cD.shiftInterval += cD.shiftInc;
                    if (cD.shiftInterval <= cD.shiftMin) {
                        cD.shiftInc = fabsf(cD.shiftInc);
                        cD.shiftInterval = cD.shiftMin;
                    } else if (cD.shiftInterval >= cD.shiftMax) {
                        cD.shiftInc = -fabsf(cD.shiftInc);
                        cD.shiftInterval = cD.shiftMax;
                    }

                    // --- Fractional Delay Calculation ---
                    float readPos = (float)cD.playInterval + cD.shiftInterval;

                    // Circular Wrap
                    while (readPos < 0.0f) readPos += bufSizeFloat;
                    while (readPos >= bufSizeFloat) readPos -= bufSizeFloat;

                    // Linear Interpolation
                    int32_t indexA = (int32_t)readPos;
                    int32_t indexB = (indexA + 1) % bufSizeInt;
                    float frac = readPos - (float)indexA;

                    float sampleA = chorusBuffer[indexA];
                    float sampleB = chorusBuffer[indexB];
                    float interpolated = sampleA + ((sampleB - sampleA) * frac);

                    // Accumulate voice output
                    dataChorusAccum += interpolated * cD.mix;
                }

                // 2. FEEDBACK & BUFFER WRITE
                // Apply feedback and write to the circular buffer.
                float feedbackSignal = input + (dataChorusAccum * chorus_.feedback);

                // Anti-denormal for stability
                if (fabsf(feedbackSignal) < 1.0e-15f) feedbackSignal = 0.0f;

                if (effect_.genTransition.active) {
                    chorusBuffer[recIdx] = feedbackSignal * effect_.genTransition.activeRecordWet;
                } else {
                    chorusBuffer[recIdx] = feedbackSignal;
                }

                // 3. OUTPUT MIXING
                // Maps menu values (0-100) to linear dry/wet levels.
                float dryLevel = (float)chorus_.eDry * kInv100;
                float wetLevel = (float)chorus_.fWet * kInv100;

                // Mix the modulated signal (Wet) with the pure original input (Dry).
                float mixData = (dataChorusAccum * wetLevel) + (input * dryLevel);

                if (effect_.genTransition.active) {
                    output = (mixData * effect_.genTransition.activeWet) + (input * effect_.genTransition.activeDry);
                } else {
                    output = mixData;
                }

                // 4. INDEX MANAGEMENT
                // Advance pointers for next sample
                recIdx = (recIdx + 1) % bufSizeInt;
                chorus_.recordInterval = recIdx;

                for (uint8_t i = 0; i < 2; i++) {
                    chorus_.chorusDelay[i].playInterval = (chorus_.chorusDelay[i].playInterval + 1) % bufSizeInt;
                }
            } break;

            case EF_FLANGER: {
                // 1. SETUP & CACHING
                Flanger& flanger_ = effect_.flanger;
                float* flangerBuf = effect_.flangerBuffer;  // Access external circular buffer

                const float bufSizeF = (float)kFlangerBufferSize;
                const int32_t bufSizeInt = (int32_t)kFlangerBufferSize;
                const float kInv100 = 0.01f;

                // Cache State Variables for local processing speed
                uint32_t pIdx = flanger_.playInterval;
                uint32_t rIdx = flanger_.recordInterval;
                float shiftInt = flanger_.shiftInterval;
                float shiftInc = flanger_.shiftInc;

                // 2. MODULATED READ POSITION (Fractional Delay)
                // Compute the modulated read head position based on triangle LFO.
                float readPos = (float)pIdx - shiftInt;  // Subtracting moves the read head "further" back

                // Circular Wrap for the fractional read position
                while (readPos < 0.0f) readPos += bufSizeF;
                while (readPos >= bufSizeF) readPos -= bufSizeF;

                // Calculate Interpolation Indices
                int32_t indexA = (int32_t)readPos;
                int32_t indexB = indexA + 1;
                if (indexB >= bufSizeInt) indexB = 0;

                // Fractional component for linear interpolation
                float frac = readPos - (float)indexA;

                // Perform Linear Interpolation between two buffer samples
                float sampleA = flangerBuf[indexA];
                float sampleB = flangerBuf[indexB];
                float dataFlanger = sampleA + ((sampleB - sampleA) * frac);

                // 3. FEEDBACK & WRITE
                // Apply feedback and store the sum in the buffer at the write head
                float feedbackSignal = dataFlanger * flanger_.feedback;
                float writeVal = input + feedbackSignal;

                // Handling transition wet/dry for recording
                if (effect_.genTransition.active) {
                    flangerBuf[rIdx] = writeVal * effect_.genTransition.activeRecordWet;
                } else {
                    flangerBuf[rIdx] = writeVal;
                }

                // 4. OUTPUT MIXING
                // Correct dry/wet mapping: input is pure dry, dataFlanger is pure wet.
                float dryLevel = (float)flanger_.eDry * kInv100;
                float wetLevel = (float)flanger_.fWet * kInv100;

                float mixData = (dataFlanger * wetLevel) + (input * dryLevel);

                // Apply global crossfade transition logic
                if (effect_.genTransition.active) {
                    output = (mixData * effect_.genTransition.activeWet) + (input * effect_.genTransition.activeDry);
                } else {
                    output = mixData;
                }

                // 5. UPDATE LFO & CIRCULAR INDICES
                // Advance the triangle LFO phase
                shiftInt += shiftInc;

                // Bounce the LFO when reaching min/max bounds (Triangle behavior)
                if (shiftInt <= flanger_.shiftMin) {
                    shiftInc = fabsf(shiftInc);  // Force positive increment
                    shiftInt = flanger_.shiftMin;
                } else if (shiftInt >= flanger_.shiftMax) {
                    shiftInc = -fabsf(shiftInc);  // Force negative increment
                    shiftInt = flanger_.shiftMax;
                }

                // Advance write and base read heads
                if (++pIdx >= bufSizeInt) pIdx = 0;
                if (++rIdx >= bufSizeInt) rIdx = 0;

                // Store updated state back to struct
                flanger_.playInterval = pIdx;
                flanger_.recordInterval = rIdx;
                flanger_.shiftInterval = shiftInt;
                flanger_.shiftInc = shiftInc;
            } break;

            case EF_PHASER: {
                // 1. SETUP & CACHING
                // Reference the phaser instance and cache essential values.
                Phaser& phaser_ = effect_.phaser;
                const float kInvSampleRate = 1.0f / AUDIO_SAMPLE_RATE;
                const float kInv100 = 0.01f;

                // 2. LFO & MODULATION
                // Advance LFO phase accumulator
                phaser_.dataX += phaser_.Ts;
                phaser_.dataY = phaser_.rate * phaser_.dataX;

                // Wrap LFO phase to stay within [0.0, 1.0]
                if (phaser_.dataY >= 1.0f) {
                    phaser_.dataX = 0.0f;
                    phaser_.dataY = 0.0f;
                }

                // Calculate Sine LFO and modulate the target frequency
                float lfoOsc = sinFast(phaser_.dataY);
                float lfoFreq = (phaser_.depthFreq * lfoOsc) + phaser_.centerFreq;

                // 3. FEEDBACK LOOP
                // Inject a portion of the previous output back into the input.
                // This creates the "peaks" and "valleys" characteristic of a resonant phaser.
                float feedbackSignal = phaser_.lastOutput * phaser_.feedback;
                float stage1Input = input + feedbackSignal;

                // 4. COEFFICIENT CALCULATION
                // Recalculate filter coefficients based on the current LFO frequency.
                float normFreq = lfoFreq * kInvSampleRate;
                float sinVal = sinFast(normFreq);
                float cosVal = cosFast(normFreq);

                // All-pass filter design: Standard Bi-quad coefficients
                float alpha = sinVal / (2.0f * phaser_.Q);
                float inv_a0 = 1.0f / (1.0f + alpha);
                float c_side = (1.0f - alpha) * inv_a0;
                float c_mid = (-2.0f * cosVal) * inv_a0;

                // 5. STAGE 1 PROCESSING (First All-Pass Filter)
                // Using the history buffers ff[0,1] and fb[0,1]
                float stage1Output = (c_side * stage1Input) + (c_mid * phaser_.ff[0]) + phaser_.ff[1] - (c_mid * phaser_.fb[0]) - (c_side * phaser_.fb[1]);

                // Update Stage 1 History
                phaser_.ff[1] = phaser_.ff[0];
                phaser_.ff[0] = stage1Input;
                phaser_.fb[1] = phaser_.fb[0];
                phaser_.fb[0] = stage1Output;

                // 6. STAGE 2 PROCESSING (Second All-Pass Filter)
                // Using history buffers ff[2,3] and fb[2,3].
                float stage2Output = (c_side * stage1Output) + (c_mid * phaser_.ff[2]) + phaser_.ff[3] - (c_mid * phaser_.fb[2]) - (c_side * phaser_.fb[3]);

                // Update Stage 2 History
                phaser_.ff[3] = phaser_.ff[2];
                phaser_.ff[2] = stage1Output;
                phaser_.fb[3] = phaser_.fb[2];
                phaser_.fb[2] = stage2Output;

                // Anti-denormal and State Storage for next iteration
                if (fabsf(stage2Output) < 1.0e-18f) stage2Output = 0.0f;  //
                phaser_.lastOutput = stage2Output;

                // 7. OUTPUT MIXING & TRANSITION
                // Mix Wet and Dry signals based on menu parameters (0-100 scale).
                float dryLevel = (float)phaser_.eDry * kInv100;
                float wetLevel = (float)phaser_.fWet * kInv100;
                float mixData = (stage2Output * wetLevel) + (input * dryLevel);

                // Apply global transition logic
                if (effect_.genTransition.active) {
                    output = (mixData * effect_.genTransition.activeWet) + (input * effect_.genTransition.activeDry);
                } else {
                    output = mixData;
                }
            } break;

            case EF_COMPRESSOR: {
                // 1. SETUP & DEFINITIONS
                // Resolve compressor parameters and local envelope variables.
                Compressor& comp_ = effect_.compressor;

                // Local Cache
                float threshold = comp_.threshold;
                float gainSmooth = comp_.gainSmoothPrev;
                float attackAlpha = comp_.attackAlpha;
                float releaseAlpha = comp_.releaseAlpha;

                // Signal Variables
                float absInput, in_dB;
                float gain_reduction = 0.0f;
                float attenuation = 1.0f;
                float mixData;

                // Constants
                const float kMinLogdB = -96.0f;
                const float kIdleThreshold = -0.001f;

                // 2. INPUT ANALYSIS (Level Detection)
                // Convert input magnitude to dB domain with floor protection.
                absInput = fabsf(input);

                // Avoid log(0)
                if (absInput < 1.0e-6f) absInput = 1.0e-6f;

                // Fast Linear to dB Conversion
                in_dB = fast_lin2db(absInput);
                if (in_dB < kMinLogdB) in_dB = kMinLogdB;

                // 3. GAIN CALCULATION (Optimized Math)
                // Compute gain reduction only when signal exceeds threshold.
                if (in_dB > threshold) {
                    float diff = in_dB - threshold;
                    float ratioInv = 1.0f / comp_.rate;
                    gain_reduction = diff * (ratioInv - 1.0f);
                }

                // else: gain_reduction remains 0.0f

                // 4. ENVELOPE (Ballistics)
                // Smooth gain changes using attack/release envelope behavior.
                if (gain_reduction >= kIdleThreshold && gainSmooth >= kIdleThreshold) {
                    gainSmooth = 0.0f;
                    attenuation = 1.0f;
                } else {
                    // Determine Alpha (Attack or Release)
                    float alpha = (gain_reduction < gainSmooth) ? attackAlpha : releaseAlpha;

                    // One-Pole Filter Application
                    gainSmooth = ((1.0f - alpha) * gain_reduction) + (alpha * gainSmooth);

                    // Convert dB back to Linear Gain
                    attenuation = fast_db2lin(gainSmooth);
                }

                // Write back state to struct
                comp_.gainSmoothPrev = gainSmooth;

                // 5. OUTPUT MIX & TRANSITION
                // Apply attenuation, mix wet/dry path, and handle transitions.
                mixData = (input * attenuation * effect_.wetFloat) + (input * effect_.dryFloat);
                if (effect_.genTransition.active) {
                    output = (mixData * effect_.genTransition.activeWet) + (input * effect_.genTransition.activeDry);
                } else {
                    output = mixData;
                }
            } break;

            case EF_EXPANDER: {
                // 1. SETUP & DEFINITIONS
                // Resolve expander parameters and local envelope variables.
                Expander& exp_ = effect_.expander;

                // Local Cache
                float threshold = exp_.threshold;
                float gainSmooth = exp_.gainSmoothPrev;
                float attackAlpha = exp_.attackAlpha;
                float releaseAlpha = exp_.releaseAlpha;
                float rate = exp_.rate;

                // Signal Variables
                float absInput, in_dB;
                float gain_change = 0.0f;
                float attenuation = 1.0f;
                float mixData;

                // Constants
                const float kMinLogdB = -144.0f;
                const float kIdleThreshold = -0.001f;

                // 2. INPUT ANALYSIS
                // Convert input magnitude to dB domain with floor protection.
                absInput = fabsf(input);

                // Prevent log(0)
                if (absInput < 1.0e-9f) absInput = 1.0e-9f;

                // Fast Linear to dB
                in_dB = fast_lin2db(absInput);
                if (in_dB < kMinLogdB) in_dB = kMinLogdB;

                // 3. GAIN CALCULATION (Optimized Math)
                // Compute attenuation when signal drops below threshold.
                if (in_dB < threshold) {
                    float diff = in_dB - threshold;
                    gain_change = diff * (rate - 1.0f);
                }

                // else: gain_change remains 0.0f (Unity Gain)

                // 4. ENVELOPE (Ballistics)
                // Smooth attenuation changes using attack/release envelope logic.
                if (gain_change >= kIdleThreshold && gainSmooth >= kIdleThreshold) {
                    gainSmooth = 0.0f;
                    attenuation = 1.0f;
                } else {
                    // Determine Alpha
                    float alpha;
                    if (gain_change > gainSmooth) {
                        alpha = attackAlpha;
                    } else {
                        alpha = releaseAlpha;
                    }

                    // One-Pole Filter
                    gainSmooth = ((1.0f - alpha) * gain_change) + (alpha * gainSmooth);

                    // Convert dB back to Linear
                    attenuation = fast_db2lin(gainSmooth);
                }

                // Write back state to struct
                exp_.gainSmoothPrev = gainSmooth;

                // 5. OUTPUT MIX & TRANSITION
                // Apply gain change, mix wet/dry path, and handle transitions.
                mixData = (input * attenuation * effect_.wetFloat) + (input * effect_.dryFloat);
                if (effect_.genTransition.active) {
                    output = (mixData * effect_.genTransition.activeWet) + (input * effect_.genTransition.activeDry);
                } else {
                    output = mixData;
                }
            } break;

            case EF_OVERDRIVE: {
                // 1. SETUP & CACHING
                // Reference the overdrive instance and cache values for performance.
                Overdrive& ov_ = effect_.overdrive;

                // Constants for cubic waveshaping and mixing
                const float kThird = 0.33333333f;      // 1/3
                const float kTwoThirds = 0.66666667f;  // 2/3
                const float kInv100 = 0.01f;           // 1/100 for percentage to linear conversion

                // Cache Parameters
                float gain = ov_.gain;
                float threshold = ov_.threshold;
                float alpha = ov_.preFilterAlpha;

                // 2. PRE-EMPHASIS (Drive Color Filter)
                // A One-Pole High-Pass filter applied BEFORE distortion.
                float hp_input = input;
                float hp_output = hp_input - ov_.hp_z1;
                ov_.hp_z1 = (hp_input * alpha) + (ov_.hp_z1 * (1.0f - alpha));

                // 3. CUBIC WAVESHAPING (Overdrive Core)
                // Apply gain and then the cubic soft-clipping curve.
                float driveSignal = hp_output * gain;
                float shapedSignal;

                // Calculate threshold limits based on the cubic algorithm
                float th_limit = kTwoThirds * threshold;

                if (driveSignal < -threshold) {
                    shapedSignal = -th_limit;
                } else if (driveSignal > threshold) {
                    shapedSignal = th_limit;
                } else {
                    // The core cubic function: x - (x^3 / 3)
                    shapedSignal = driveSignal - ((driveSignal * driveSignal * driveSignal) * kThird);
                }

                // 4. POST-FILTER (Tone Shaping)
                // Direct Form II Biquad Filter.
                float x0 = shapedSignal;
                float y0 = (ov_.a0 * x0) + (ov_.a1 * ov_.lp_x1) + (ov_.a2 * ov_.lp_x2) - (ov_.b1 * ov_.lp_y1) - (ov_.b2 * ov_.lp_y2);

                // Update Biquad Filter state history
                ov_.lp_x2 = ov_.lp_x1;
                ov_.lp_x1 = x0;
                ov_.lp_y2 = ov_.lp_y1;
                ov_.lp_y1 = y0;

                // 5. OUTPUT MIXING & TRANSITION
                float dryLevel = (float)ov_.eDry * kInv100;
                float wetLevel = (float)ov_.fWet * kInv100;

                // Combine processed (Wet) and original (Dry) signals
                float mixData = (y0 * wetLevel) + (input * dryLevel);

                // Apply global crossfade transition logic
                if (effect_.genTransition.active) {
                    output = (mixData * effect_.genTransition.activeWet) + (input * effect_.genTransition.activeDry);
                } else {
                    output = mixData;
                }
            } break;

            case EF_DISTORTION: {
                // 1. SETUP & CACHING
                // Reference the distortion instance and cache values for performance.
                Distortion& dist_ = effect_.distortion;
                const float kInv100 = 0.01f;

                // Parameters for waveshaping
                float gain = dist_.gain;
                float threshold = dist_.threshold;
                float bias = dist_.bias;

                // Filter Coefficients
                float a0 = dist_.a0, a1 = dist_.a1, a2 = dist_.a2;
                float b1 = dist_.b1, b2 = dist_.b2;

                // 2. ASYMMETRIC WAVESHAPING (The Distortion Algorithm)
                // First, we boost the input and apply the DC bias (Asymmetry).
                // Shifting the waveform before clipping creates even-order harmonics (warmth).
                float driveSignal = (input * gain) + bias;
                float shapedSignal;

                if (gain > 0.0001f) {
                    // ARCTAN SOFT CLIPPER:
                    // (2/PI) * atan(x) provides a smooth, musical transition into distortion.
                    // We multiply by threshold to set the final ceiling level.
                    shapedSignal = ((2.0f / M_PI) * atanFast(driveSignal)) * threshold;

                    // COMPENSATE DC OFFSET:
                    // Asymmetric clipping shifts the waveform's center.
                    // We subtract a portion of the bias to keep the signal centered around 0.
                    shapedSignal -= (bias * 0.5f);
                } else {
                    // Passthrough behavior if gain is nearly zero.
                    shapedSignal = input * threshold;
                }

                // 3. BIQUAD FILTER STAGE (Direct Form II)
                // Process the distorted signal through the Tone filter.
                // Using float states (x1, x2, y1, y2) for maximum precision.
                float x0 = shapedSignal;
                float y0 = (a0 * x0) + (a1 * dist_.x1) + (a2 * dist_.x2) - (b1 * dist_.y1) - (b2 * dist_.y2);

                // Update Filter State History
                dist_.x2 = dist_.x1;
                dist_.x1 = x0;
                dist_.y2 = dist_.y1;
                dist_.y1 = y0;

                // 4. OUTPUT MIXING
                // Maps menu values (0-100) to linear dry/wet levels.
                float dryLevel = (float)dist_.eDry * kInv100;
                float wetLevel = (float)dist_.fWet * kInv100;

                // Combine the processed (Wet) signal with the original (Dry) input.
                float mixData = (y0 * wetLevel) + (input * dryLevel);

                // 5. GLOBAL TRANSITION
                // Handle smooth crossfades between different effect presets or bypass states.
                if (effect_.genTransition.active) {
                    output = (mixData * effect_.genTransition.activeWet) + (input * effect_.genTransition.activeDry);
                } else {
                    output = mixData;
                }
            } break;

            case EF_BITCRUSHER: {
                // 1. REFERENCE & CACHING
                // Access the bitcrusher instance and cache variables for performance.
                Bitcrusher& bit_ = effect_.bitcrusher;

                const float kScale24Bit = 16777215.0f;        // 0xFFFFFF
                const float kInvScale24Bit = 5.96046448e-8f;  // 1.0 / 16777215.0
                const float kGateThresh = 0.002f;             // Silence gate threshold

                // Local cache for processing
                uint32_t counter = bit_.sampleCounter;
                uint32_t maxCount = bit_.sampleCounterMax;
                float currentSample = bit_.sampleData;
                float limPos = bit_.limitPos;
                float limNeg = bit_.limitNeg;
                uint32_t resMask = bit_.resModifier;

                // 2. DOWNSAMPLING & DISTORTION LOGIC
                // Increment local counter to handle Sample Rate Reduction.
                counter++;

                if (counter >= maxCount) {
                    counter = 0;  // Reset cadence counter
                    float processed = input;

                    // Silence Gate: Prevent processing low-level noise.
                    if (fabsf(processed) < kGateThresh) {
                        currentSample = 0.0f;
                    } else {
                        // --- DISTORTION MODE (dSmooth / Mode Selection) ---
                        if (bit_.mode == BIT_FOLD) {
                            // WAVEFOLDING: Reflects the signal back when it exceeds thresholds.
                            // Creates rich, complex harmonics compared to hard clipping.
                            while (processed > limPos || processed < limNeg) {
                                if (processed > limPos) {
                                    processed = limPos - (processed - limPos);
                                }
                                if (processed < limNeg) {
                                    processed = limNeg - (processed - limNeg);
                                }
                            }
                        } else {
                            // HARD CLIPPING: Simply clamps the signal at the thresholds.
                            if (processed > limPos)
                                processed = limPos;
                            else if (processed < limNeg)
                                processed = limNeg;
                        }

                        // --- BIT DEPTH REDUCTION (Quantization) ---
                        // Normalize [-1.0, 1.0] to [0.0, 1.0] for integer masking.
                        float normalized = (processed + 1.0f) * 0.5f;

                        // Scale to 24-bit integer space and apply the bitmask.
                        uint32_t scaled = (uint32_t)(normalized * kScale24Bit);
                        scaled &= resMask;

                        // Convert back to float and expand to audio range [-1.0, 1.0].
                        currentSample = ((float)scaled * kInvScale24Bit * 2.0f) - 1.0f;
                    }
                }

                // 3. SMOOTHING FILTER (One-Pole Low Pass)
                // Runs at full sample rate to smooth out the staircase edges from downsampling.
                // This reduces harsh digital "buzz" and makes the effect more musical.
                float filteredSample = bit_.lastOutput + bit_.smoothAlpha * (currentSample - bit_.lastOutput);
                bit_.lastOutput = filteredSample;  // Update filter state

                // 4. FINAL OUTPUT MIXING
                // Mix the processed (Wet) signal with the original (Dry) input.
                float mixData = (filteredSample * effect_.wetFloat) + (input * effect_.dryFloat);

                // Apply global transition blend if a preset/effect change is active.
                if (effect_.genTransition.active) {
                    output = (mixData * effect_.genTransition.activeWet) + (input * effect_.genTransition.activeDry);
                } else {
                    output = mixData;
                }

                // 5. STATE UPDATE
                // Persist local values back to the struct for the next interrupt cycle.
                bit_.sampleCounter = counter;
                bit_.sampleData = currentSample;

            } break;

            default:
                output = input;
                break;
        }
    } else {
        // BYPASS OUTPUT
        // Return original input when effect path is inactive.
        output = input;
    }
    return output;
}

float Controller::processAudioLpfHelper(uint8_t lpfNum_, float audio_) {
    /// @brief Processes a single audio sample through a biquad low-pass filter (LPF) using Direct Form I calculation with history management and wet/dry mixing.

    // 1. LPF STATE RESOLUTION
    // Resolve LPF reference and bypass inactive path.
    Lpf& lpf_ = lpf[lpfNum_];
    if (!lpf_.active) return audio_;

    // 2. INPUT PREPARATION
    // Add anti-denormal noise for stable low-level processing.
    float input = audio_ + FILTER_ANTI_DENORMAL;

    // 3. BIQUAD CALCULATION
    // Compute LPF sample using Direct Form I coefficients.
    float filteredSignal = (lpf_.a0 * input) + (lpf_.a1 * lpf_.dataIn[1]) + (lpf_.a2 * lpf_.dataIn[2]) - (lpf_.b1 * lpf_.dataOut[1]) - (lpf_.b2 * lpf_.dataOut[2]);

    // 4. FILTER HISTORY UPDATE
    // Shift input and output delay-line history buffers.
    lpf_.dataIn[2] = lpf_.dataIn[1];
    lpf_.dataIn[1] = input;

    lpf_.dataOut[2] = lpf_.dataOut[1];
    lpf_.dataOut[1] = filteredSignal;

    // 5. WET/DRY MIX OUTPUT
    // Blend filtered and dry sample, then return final output.
    return (filteredSignal * lpf_.wet) + (audio_ * lpf_.dry);
}

////////////////////////////////////////////////////////////////////////////////
/* Interrupt Functions -------------------------------------------------------*/
////////////////////////////////////////////////////////////////////////////////

void Controller::interruptPlay() {
    /// @brief The central heartbeat of the sequencer. Manages metronome pre-counts, real-time beat triggering for all layers (simple and complex fills), hardware sync pulses, and LFO phase synchronization.

    if (playActive) {
        // 1. METRONOME PRE-COUNT PHASE
        // Handle the "get ready" timeline before normal song playback starts.

        if (metronome.precountState) {
            // Trigger Bar/Measure clicks based on pre-counter position
            if ((metronome.precounter % barInterval == 0) && (!io.sync.slaveMode)) {
                // Initialize Bar Click (Higher Pitch/Accent)
                metroPlayData.active = true;
                metroPlayData.sample = metronome.sample;
                metroPlayData.barMeasure = 0;
                metroPlayData.counter = 0;
                metroPlayData.counterMax = kMetroSize - 1;
                metroPlayData.volumeMultiplier = kLayerVolumeCoef * metronome.volumeFloat * mixer.masterVolumeFloat;
                metroPlayData.mixerInMode = metronome.mixerInMode;
                metronome.countDownFlag = true;
            } else if ((metronome.precounter % measureInterval == 0) && (!io.sync.slaveMode)) {
                // Initialize Measure Click (Standard Pitch)
                metroPlayData.active = true;
                metroPlayData.sample = metronome.sample;
                metroPlayData.barMeasure = 1;
                metroPlayData.counter = 0;
                metroPlayData.counterMax = kMetroSize - 1;
                metroPlayData.volumeMultiplier = kLayerVolumeCoef * metronome.volumeFloat * mixer.masterVolumeFloat;
                metroPlayData.mixerInMode = metronome.mixerInMode;
                metronome.countDownFlag = true;
            }

            // Increment pre-count or transition to active playback
            if (metronome.precounter < metronome.precounterMax) {
                metronome.precounter += 1;
            } else {
                metronome.precounter = 0;
                metronome.precountState = false;

                // Commit any hits captured during precount to wherever playback is
                // about to resume (playInterval — not necessarily 0, since the song
                // can start mid-loop), right now, so they land in bank.beatLibrary in
                // time for the very next tick's beat-trigger pass to play them in sync.
                for (uint8_t i = 0; i < kLayerLibrarySize; i++) {
                    if (precountPendingBeat[i]) {
                        precountPendingBeat[i] = false;
                        layerSong_setBeat(i, activeSongBank, playInterval, 0, 0, 0, 0, true);
                    }
                }
            }
        }

        // 2. STANDARD PLAYBACK PHASE
        // Handle runtime metronome, sync pulses, beat triggering, and loop flow.

        else {
            if (io.midi.txStartPending && io.midi.txTransport) {
                static const uint8_t kMidiStart = 0xFA;
                enqueueMidiTx(&kMidiStart, 1);
                io.midi.txStartPending = false;
            }

            // Handle metronome clicks during active recording sessions
            if ((recordActive) && (metronome.active) && (playInterval != songInterval)) {
                if ((playInterval % barInterval == 0) && (!io.sync.slaveMode)) {
                    metroPlayData.active = true;
                    metroPlayData.sample = metronome.sample;
                    metroPlayData.barMeasure = 0;
                    metroPlayData.counter = 0;
                    metroPlayData.counterMax = kMetroSize - 1;
                    metroPlayData.volumeMultiplier = kLayerVolumeCoef * metronome.volumeFloat * mixer.masterVolumeFloat;
                } else if ((playInterval % measureInterval == 0) && (!io.sync.slaveMode)) {
                    metroPlayData.active = true;
                    metroPlayData.sample = metronome.sample;
                    metroPlayData.barMeasure = 1;
                    metroPlayData.counter = 0;
                    metroPlayData.counterMax = kMetroSize - 1;
                    metroPlayData.volumeMultiplier = kLayerVolumeCoef * metronome.volumeFloat * mixer.masterVolumeFloat;
                }
            }

            // 3. LAYER BEAT PROCESSING
            // Iterate through all layers and trigger simple/complex beat events.
            for (uint8_t i = 0; i < kLayerLibrarySize; i++) {
                Layer& layer = layerLibrary[i];
                Bank& bank = layer.bankLibrary[activeSongBank];
                int8_t playBeatNum = bank.playBeatNum;
                int8_t playBeatMicroNum = bank.playBeatMicroNum;
                float fillVolMultiplier = 0.0f;

                if ((bank.lastActiveBeatNum != -1) && (playBeatNum != -1)) {
                    Beat& beat = bank.beatLibrary[playBeatNum];

                    // SIMPLE BEAT HANDLING
                    // Trigger simple beats at the main beat interval.
                    if ((beat.getFillType() == 0) && (beat.getFillPattern() <= 2) && (beat.getFillTarget() == NULL_FILL_TARGET)) {
                        if (beat.getStartInterval() == playInterval) {
                            if ((!layer.mute) && (layer.samplePlay)) {
                                switch (beat.getFillPattern()) {
                                    case 0:
                                        fillVolMultiplier = kNumberDataLibrary[100].powMultiplier;
                                        break;  // FLAT: 100% velocity

                                    case 1:
                                        fillVolMultiplier = kNumberDataLibrary[50].powMultiplier;
                                        break;  // GHOST: 50% velocity

                                    case 2:
                                        break;  // MUTED: 0% velocity
                                }
                            }
                            if (fillVolMultiplier > 0.0f) layer_playBeat(layer.number, fillVolMultiplier);

                            // Advance to the next beat index
                            (playBeatNum < bank.lastActiveBeatNum) ? bank.playBeatNum += 1 : bank.playBeatNum = 0;
                            Beat& nextBeat = bank.beatLibrary[bank.playBeatNum];
                            ((nextBeat.getFillType() == 0) && (nextBeat.getFillPattern() <= 2)) ? bank.playBeatMicroNum = -1 : bank.playBeatMicroNum = 0;
                        }
                    }

                    // COMPLEX FILL HANDLING
                    // Trigger micro-step fill events using beat fill timing data.
                    else if ((beat.getFillTarget() != NULL_FILL_TARGET) && (playBeatMicroNum != -1)) {
                        BeatMicro& beatMicro = bank.beatFillLibrary[beat.getFillTarget()].beatMicroLibrary[playBeatMicroNum];
                        if (beatMicro.getInterval() == playInterval) {
                            if ((!layer.mute) && (layer.samplePlay) && ((playBeatMicroNum == 0) || ((playBeatMicroNum != 0) && (layer.fill)))) {
                                fillVolMultiplier = kNumberDataLibrary[beatMicro.getLevel()].powMultiplier;
                                if (fillVolMultiplier > 0.0f) layer_playBeat(layer.number, fillVolMultiplier);
                            }

                            // Advance micro-step index within the fill
                            if (playBeatMicroNum < (bank.beatFillLibrary[beat.getFillTarget()].getStepSize() - 1)) {
                                bank.playBeatMicroNum += 1;
                            } else {
                                (playBeatNum < bank.lastActiveBeatNum) ? bank.playBeatNum += 1 : bank.playBeatNum = 0;
                                Beat& nextBeat = bank.beatLibrary[bank.playBeatNum];
                                ((nextBeat.getFillType() == 0) && (nextBeat.getFillPattern() <= 2)) ? bank.playBeatMicroNum = -1 : bank.playBeatMicroNum = 0;
                            }
                        }
                    }
                }
            }

            // 4. SONG NAVIGATION & LOOP MANAGEMENT
            // Advance timeline, evaluate stop/reset triggers, and handle loop wrap.
            playInterval += 1;
            if (playInterval < songInterval) {
                // Handle pending Stop/Reset requests with visual feedback
                if (stopFlag) {
                    if ((io.syncOut == 2) && io.sync.syncOutPlay) {
                        constexpr uint16_t kSyncModeBStopGateLeadFrames = 2;
                        if ((stopInterval > playInterval) &&
                            ((stopInterval - playInterval) <= kSyncModeBStopGateLeadFrames)) {
                            HAL_GPIO_WritePin(SYNC_OUT_GATE_GPIO_Port, SYNC_OUT_GATE_Pin, GPIO_PIN_RESET);
                        }
                    }

                    if (stopInterval == playInterval)
                        stop();
                    else if (playInterval % (measureInterval / 2) == 0) {
                        stopIcon.flag = true;
                        stopIcon.mode = !stopIcon.mode;  // Toggle icon for blinking effect
                    }
                }
                if (resetFlag) {
                    if (resetInterval == playInterval)
                        reset();
                    else if (playInterval % (measureInterval / 2) == 0) {
                        resetIcon.flag = true;
                        resetIcon.mode = !resetIcon.mode;
                    }
                }
            } else {
                // LOOP END PROCEDURES
                // Reset play interval and apply end-of-loop bank/play pointer updates.
                playInterval = 0;
                io.sync.txPulseCounter = 0;

                // Handle Bank Shifting at the end of the loop cycle
                if (bankShiftFlag) {
                    bankShiftFlag = false;
                    activeSongBank = targetSongBank;
                    bankActionFlag = true;
                }

                // Reset all layer playback pointers for the new loop
                for (uint8_t i = 0; i < kLayerLibrarySize; i++) {
                    Layer& layer = layerLibrary[i];
                    Bank& bank = layer.bankLibrary[activeSongBank];
                    if (bank.lastActiveBeatNum != -1) {
                        bank.playBeatNum = 0;
                        ((bank.beatLibrary[bank.playBeatNum].getFillType() == 0) && (bank.beatLibrary[bank.playBeatNum].getFillPattern() <= 2)) ? bank.playBeatMicroNum = -1 : bank.playBeatMicroNum = 0;
                    } else {
                        bank.playBeatNum = -1;
                        bank.playBeatMicroNum = -1;
                    }
                }
                lcd_restartPlay();
            }
        }
    }

    // 5. MICRO-TIMING & MODULATION UPDATES
    // Update temporary timing delays and LFO counters after transport operations.
    for (uint8_t i = 0; i < kLayerLibrarySize; i++) {
        LayerPlayData& lD = layerPlayData[i];
        if (lD.tempBeatTimingFlag) {
            if (lD.tempBeatTimingCounter < lD.tempBeatTimingCounterMax) {
                lD.tempBeatTimingCounter += 1;
            } else {
                lD.tempBeatTimingFlag = false;
                uint32_t primaskTiming = __get_PRIMASK();
                __disable_irq();
                memcpy(&lD.activeBeatPlayData, &lD.tempBeatPlayData, sizeof(BeatPlayData));
                __set_PRIMASK(primaskTiming);
            }
        }
    }

    // LFO POSITION UPDATE
    // Increment and wrap LFO counters, then resynchronize phase at measure boundaries.
    for (uint8_t i = 0; i < kLfoLibrarySize; i++) {
        Lfo& lfo = lfoLibrary[i];
        lfo.sampleCounter += lfo.sampleInc;
        if (lfo.sampleCounter >= kLfoSampleSize) {
            lfo.sampleCounter -= kLfoSampleSize;
        }

        // Resynchronize LFO phase at every measure start to prevent drift
        if ((playActive) && (playInterval % measureInterval == 0)) {
            if ((lfo.sampleCounter <= 1.0f) || (lfo.sampleCounter > (kLfoSampleSize - 1))) lfo.sampleCounter = 0.0f;
        }
    }
}

void Controller::interruptSyncInGate() {
    /// @brief Handles SYNC-IN gate edges (MODE-B only) for external play/stop control.

    if (io.syncIn != 2) return;

    bool gateHigh = (HAL_GPIO_ReadPin(SYNC_IN_GATE_GPIO_Port, SYNC_IN_GATE_Pin) == GPIO_PIN_SET);

    if (gateHigh != io.sync.rxGateHigh) {
        io.sync.rxGateHigh = gateHigh;
        if (gateHigh) {
            io.sync.rxPlayFlag = true;
        } else {
            io.sync.rxStopFlag = true;
        }
    }
}

void Controller::interruptSyncInPulse() {
    /// @brief Handles an incoming sync pulse on SYNC_IN_Pin. Called from EXTI ISR.
    /// Measures interval between consecutive pulses to derive BPM.
    /// In MODE-A, pulses can start transport when play/record is armed.

    if (io.syncIn > 0) {
        LED1_TOGGLE;
    }

    // 1. MODE GUARD
    // Active for MODE-A/B; OFF mode exits immediately.
    if (io.syncIn == 0) return;

    // 2. HIGH-RES INTERVAL MEASUREMENT
    // Use microsecond timing to avoid 1 ms quantization jitter (e.g. 129<->130 BPM bouncing).
    static uint32_t rxPulseLastUs = 0;
    static uint32_t rxPulseFilteredUs = 0;

    uint32_t nowMs = HAL_GetTick();
    uint32_t nowUs = dwt_getMicros();

    // Reset local filter state when external logic resets pulse tracking.
    if (io.sync.rxPulseLastTick == 0) {
        rxPulseLastUs = 0;
        rxPulseFilteredUs = 0;
    }

    // 3. BPM DERIVATION
    // PPQN pulses per beat -> beat_us = pulse_us * ppqn -> BPM = 60,000,000 / beat_us.
    if (rxPulseLastUs > 0) {
        uint32_t intervalUs = nowUs - rxPulseLastUs;
        const uint8_t syncInPpqnIdx = (io.syncInPpqn <= kMaxIoSyncPpqn) ? io.syncInPpqn : kInitialIoSyncInPpqn;
        uint8_t ppqn = kIoSyncPpqnDataLibrary[syncInPpqnIdx].ppqn;

        uint32_t minBeatUs = 60000000UL / kMaxTempo;
        uint32_t maxBeatUs = 60000000UL / kMinTempo;
        uint32_t beatUsRaw = intervalUs * ppqn;

        if ((intervalUs > 0) && (beatUsRaw >= minBeatUs) && (beatUsRaw <= maxBeatUs)) {
            // 1st-order IIR low-pass: 75% previous + 25% new interval.
            if (rxPulseFilteredUs == 0) {
                rxPulseFilteredUs = intervalUs;
            } else {
                rxPulseFilteredUs = (rxPulseFilteredUs * 3UL + intervalUs) / 4UL;
            }

            uint32_t beatUsFiltered = rxPulseFilteredUs * ppqn;
            io.sync.rxPulseInterval = (rxPulseFilteredUs + 500UL) / 1000UL;  // keep timeout logic in ms domain
            io.sync.rxPulseBpm = (uint16_t)((60000000UL + beatUsFiltered / 2UL) / beatUsFiltered);
            io.sync.rxPulseFlag = true;
        }
    }

    // 4. ARMED START TRIGGER
    // MODE-A can start playback when armed by user action.
    // MODE-B start/stop is controlled by gate edges.
    if ((io.syncIn != 2) && (playArmed || recordArmed) && !playActive) io.sync.rxPlayFlag = true;

    // 5. TIMESTAMP UPDATE
    rxPulseLastUs = nowUs;
    io.sync.rxPulseLastTick = nowMs;
}

void Controller::interruptMidiTxClock() {
    /// @brief Transmits MIDI Clock (0xF8) on each timer tick. Called from TIM4 ISR at 24 PPQN.

    // 1. CLOCK TRANSMISSION
    // Enqueue real-time MIDI Clock byte when MIDI sync TX is active.
    if (io.midi.txClock) {
        static const uint8_t kMidiClock = 0xF8;
        enqueueMidiTx(&kMidiClock, 1);
    }

    // Sync-out clock policy:
    // MODE-A -> always running (no gate function)
    // MODE-B -> always running + gate play/stop
    // MODE-C -> running only while transport is active
    const bool syncClockEnabled = (io.syncOut == 1) || (io.syncOut == 2) || ((io.syncOut == 3) && playActive);

    if (syncClockEnabled && io.sync.syncOutBeat) {
        const uint8_t syncOutPpqnIdx = (io.syncOutPpqn <= kMaxIoSyncPpqn) ? io.syncOutPpqn : kInitialIoSyncOutPpqn;
        uint8_t ppqn = kIoSyncPpqnDataLibrary[syncOutPpqnIdx].ppqn;
        if (ppqn == 0) return;

        uint8_t ticksPerPulse = (ppqn >= 24) ? 1 : (24 / ppqn);
        if (ticksPerPulse == 0) ticksPerPulse = 1;

        io.sync.txTrsTickCounter += 1;
        if (io.sync.txTrsTickCounter >= ticksPerPulse) {
            io.sync.txTrsTickCounter = 0;
            HAL_GPIO_WritePin(SYNC_OUT_PULSE_GPIO_Port, SYNC_OUT_PULSE_Pin, GPIO_PIN_SET);
            if (io.syncOut > 0) {
                LED2_TOGGLE;
            }
            startBeatSyncTimer();
        }
    } else {
        io.sync.txTrsTickCounter = 0;
        HAL_GPIO_WritePin(SYNC_OUT_PULSE_GPIO_Port, SYNC_OUT_PULSE_Pin, GPIO_PIN_RESET);
    }
}

void Controller::interruptTransition() {
    /// @brief Global transition engine for smoothing parameter changes across the DSP pipeline.
    /// Manages linear ramps for volume, pan, and multi-phase crossfades for EQ, Filters, and Effects.

    static const float kChangeVal = 0.0002;

    // 1. SYSTEM VOLUME TRANSITION
    // Smoothly ramp master volume toward its target value.
    if (mixer.masterVolumeTransition.active) {
        MixerVolumeTransition& vTransition = mixer.masterVolumeTransition;
        switch (vTransition.actionVolume) {
            case MIXER_ACTION_UP:
                if (mixer.masterVolumeFloat >= vTransition.targetVolume) {
                    vTransition.actionVolume = MIXER_ACTION_NONE;
                } else {
                    mixer.masterVolumeFloat += kChangeVal;
                }
                break;

            case MIXER_ACTION_DOWN:
                if (mixer.masterVolumeFloat <= vTransition.targetVolume) {
                    vTransition.actionVolume = MIXER_ACTION_NONE;
                } else {
                    mixer.masterVolumeFloat -= kChangeVal;
                }
                break;
        }
        if (vTransition.actionVolume == MIXER_ACTION_NONE) {
            vTransition.active = false;
        }
    }

    // 2. SYSTEM PAN TRANSITION
    // Smoothly ramp left/right channel gains toward target pan values.
    if (mixer.panTransition.active) {
        MixerPanTransition& pTransition = mixer.panTransition;
        switch (pTransition.actionVolumeLeft) {
            case MIXER_ACTION_UP:
                if (mixer.volumeLeftFloat >= pTransition.targetVolumeLeft) {
                    pTransition.actionVolumeLeft = MIXER_ACTION_NONE;
                } else {
                    mixer.volumeLeftFloat += kChangeVal;
                }
                break;

            case MIXER_ACTION_DOWN:
                if (mixer.volumeLeftFloat <= pTransition.targetVolumeLeft) {
                    pTransition.actionVolumeLeft = MIXER_ACTION_NONE;
                } else {
                    mixer.volumeLeftFloat -= kChangeVal;
                }
                break;
        }
        switch (pTransition.actionVolumeRight) {
            case MIXER_ACTION_UP:
                if (mixer.volumeRightFloat >= pTransition.targetVolumeRight) {
                    pTransition.actionVolumeRight = MIXER_ACTION_NONE;
                } else {
                    mixer.volumeRightFloat += kChangeVal;
                }
                break;

            case MIXER_ACTION_DOWN:
                if (mixer.volumeRightFloat <= pTransition.targetVolumeRight) {
                    pTransition.actionVolumeRight = MIXER_ACTION_NONE;
                } else {
                    mixer.volumeRightFloat -= kChangeVal;
                }
                break;
        }
        if ((pTransition.actionVolumeLeft == MIXER_ACTION_NONE) && (pTransition.actionVolumeRight == MIXER_ACTION_NONE)) {
            pTransition.active = false;
        }
    }

    // 3. METRONOME VOLUME TRANSITION
    // Smoothly ramp metronome level toward its target value.
    if (metronome.volumeTransition.active) {
        MetronomeVolumeTransition& vTransition = metronome.volumeTransition;
        switch (vTransition.actionVolume) {
            case MET_ACTION_UP:
                if (metronome.volumeFloat >= vTransition.targetVolume) {
                    vTransition.actionVolume = MET_ACTION_NONE;
                } else {
                    metronome.volumeFloat += kChangeVal;
                }
                break;

            case MET_ACTION_DOWN:
                if (metronome.volumeFloat <= vTransition.targetVolume) {
                    vTransition.actionVolume = MET_ACTION_NONE;
                } else {
                    metronome.volumeFloat -= kChangeVal;
                }
                break;
        }
        if (vTransition.actionVolume == MET_ACTION_NONE) {
            vTransition.active = false;
        }
    }

    // 4. EQ CROSSFADE TRANSITION
    // Process EQ wet/dry crossfade and finalize mode transitions.
    if (eq.genTransition.active) {
        EqGenTransition& gTransition = eq.genTransition;
        switch (gTransition.actionDry) {
            case EQ_ACTION_UP:
                if (gTransition.activeDry >= gTransition.targetDry) {
                    gTransition.actionDry = EQ_ACTION_NONE;
                } else {
                    gTransition.activeDry += kChangeVal;
                }
                break;

            case EQ_ACTION_DOWN:
                if (gTransition.activeDry <= gTransition.targetDry) {
                    gTransition.actionDry = EQ_ACTION_NONE;
                } else {
                    gTransition.activeDry -= kChangeVal;
                }
                break;
        }
        switch (gTransition.actionWet) {
            case EQ_ACTION_UP:
                if (gTransition.activeWet >= gTransition.targetWet) {
                    gTransition.actionWet = EQ_ACTION_NONE;
                } else {
                    gTransition.activeWet += kChangeVal;
                }
                break;

            case EQ_ACTION_DOWN:
                if (gTransition.activeWet <= gTransition.targetWet) {
                    gTransition.actionWet = EQ_ACTION_NONE;
                } else {
                    gTransition.activeWet -= kChangeVal;
                }
                break;
        }
        if ((gTransition.actionDry == EQ_ACTION_NONE) && (gTransition.actionWet == EQ_ACTION_NONE)) {
            switch (gTransition.mode) {
                case EQ_MODE_NONE:
                    gTransition.active = false;
                    gTransition.mode = EQ_MODE_NONE;
                    gTransition.phase = EQ_PHASE_NONE;
                    transitionClearFlag = true;
                    break;

                case EQ_MODE_ACTIVE:
                    gTransition.active = false;
                    gTransition.mode = EQ_MODE_NONE;
                    gTransition.phase = EQ_PHASE_NONE;
                    transitionClearFlag = true;
                    checkMenuTransition(EQ_MENU, false);
                    checkEncoderTransition(ENC_EQ_ACTIVE, false);
                    break;
            }
        }
    }

    // 5. FILTER TRANSITIONS
    // Process filter generation/mix transitions for all filter engines.
    for (uint8_t i = 0; i < kFilterLibrarySize; i++) {
        if (filter[i].genTransition.active) {
            FilterGenTransition& gTransition = filter[i].genTransition;
            switch (gTransition.actionDry) {
                case FIL_ACTION_UP:
                    if (gTransition.activeDry >= gTransition.targetDry) {
                        gTransition.actionDry = FIL_ACTION_NONE;
                    } else {
                        gTransition.activeDry += kChangeVal;
                    }
                    break;

                case FIL_ACTION_DOWN:
                    if (gTransition.activeDry <= gTransition.targetDry) {
                        gTransition.actionDry = FIL_ACTION_NONE;
                    } else {
                        gTransition.activeDry -= kChangeVal;
                    }
                    break;
            }
            switch (gTransition.actionWet) {
                case FIL_ACTION_UP:
                    if (gTransition.activeWet >= gTransition.targetWet) {
                        gTransition.actionWet = FIL_ACTION_NONE;
                    } else {
                        gTransition.activeWet += kChangeVal;
                    }
                    break;

                case FIL_ACTION_DOWN:
                    if (gTransition.activeWet <= gTransition.targetWet) {
                        gTransition.actionWet = FIL_ACTION_NONE;
                    } else {
                        gTransition.activeWet -= kChangeVal;
                    }
                    break;
            }
            if ((gTransition.actionDry == FIL_ACTION_NONE) && (gTransition.actionWet == FIL_ACTION_NONE)) {
                switch (gTransition.mode) {
                    case FIL_MODE_NONE:
                        gTransition.active = false;
                        gTransition.mode = FIL_MODE_NONE;
                        gTransition.phase = FIL_PHASE_NONE;
                        transitionClearFlag = true;
                        break;

                    case FIL_MODE_ACTIVE:
                        gTransition.active = false;
                        gTransition.mode = FIL_MODE_NONE;
                        gTransition.phase = FIL_PHASE_NONE;
                        transitionClearFlag = true;
                        (i == 0) ? checkMenuTransition(FILTER_0_MENU, false) : checkMenuTransition(FILTER_1_MENU, false);
                        (i == 0) ? checkEncoderTransition(ENC_FILTER_0_ACTIVE, false) : checkEncoderTransition(ENC_FILTER_1_ACTIVE, false);
                        break;

                    case FIL_MODE_TYPE:
                        switch (gTransition.phase) {
                            case EF_PHASE_NONE:
                                gTransition.active = false;
                                gTransition.mode = FIL_MODE_NONE;
                                gTransition.phase = FIL_PHASE_NONE;
                                transitionClearFlag = true;
                                break;

                            case EF_PHASE_A:
                                filter[i].calculateCoef();
                                gTransition.phase = FIL_PHASE_B;
                                gTransition.activeDry = 1.0;
                                gTransition.targetDry = 0.0;
                                gTransition.activeWet = 0.0;
                                gTransition.targetWet = 1.0;
                                filter_calculateGenTransition(i);
                                transitionShowFlag = 2;
                                (i == 0) ? checkMenuTransition(FILTER_0_MENU, true) : checkMenuTransition(FILTER_1_MENU, true);
                                (i == 0) ? checkEncoderTransition(ENC_FILTER_0_TYPE, true) : checkEncoderTransition(ENC_FILTER_1_TYPE, true);
                                break;

                            case EF_PHASE_B:
                                gTransition.active = false;
                                gTransition.mode = FIL_MODE_NONE;
                                gTransition.phase = FIL_PHASE_NONE;
                                transitionClearFlag = true;
                                (i == 0) ? checkMenuTransition(FILTER_0_MENU, false) : checkMenuTransition(FILTER_1_MENU, false);
                                (i == 0) ? checkEncoderTransition(ENC_FILTER_0_TYPE, false) : checkEncoderTransition(ENC_FILTER_1_TYPE, false);
                                break;
                        }
                        break;
                }
            }
        }
        if (filter[i].mixTransition.active) {
            Filter& filter_ = filter[i];
            FilterMixTransition& mTransition = filter[i].mixTransition;
            switch (mTransition.actionDry) {
                case FIL_ACTION_UP:
                    if (filter_.dryFloat >= mTransition.targetDry) {
                        mTransition.actionDry = FIL_ACTION_NONE;
                    } else {
                        filter_.dryFloat += kChangeVal;
                    }
                    break;

                case FIL_ACTION_DOWN:
                    if (filter_.dryFloat <= mTransition.targetDry) {
                        mTransition.actionDry = FIL_ACTION_NONE;
                    } else {
                        filter_.dryFloat -= kChangeVal;
                    }
                    break;
            }
            switch (mTransition.actionWet) {
                case FIL_ACTION_UP:
                    if (filter_.wetFloat >= mTransition.targetWet) {
                        mTransition.actionWet = FIL_ACTION_NONE;
                    } else {
                        filter_.wetFloat += kChangeVal;
                    }
                    break;

                case FIL_ACTION_DOWN:
                    if (filter_.wetFloat <= mTransition.targetWet) {
                        mTransition.actionWet = FIL_ACTION_NONE;
                    } else {
                        filter_.wetFloat -= kChangeVal;
                    }
                    break;
            }
            if ((mTransition.actionDry == FIL_ACTION_NONE) && (mTransition.actionWet == FIL_ACTION_NONE)) {
                mTransition.active = false;
            }
        }
    }

    // 6. EFFECT TRANSITIONS
    // Process effect generation/mix transitions for all effect engines.
    for (uint8_t i = 0; i < kEffectLibrarySize; i++) {
        if (effect[i].genTransition.active) {
            EffectGenTransition& gTransition = effect[i].genTransition;
            switch (gTransition.actionDry) {
                case EF_ACTION_UP:
                    if (gTransition.activeDry >= gTransition.targetDry) {
                        gTransition.actionDry = EF_ACTION_NONE;
                    } else {
                        gTransition.activeDry += kChangeVal;
                    }
                    break;

                case EF_ACTION_DOWN:
                    if (gTransition.activeDry <= gTransition.targetDry) {
                        gTransition.actionDry = EF_ACTION_NONE;
                    } else {
                        gTransition.activeDry -= kChangeVal;
                    }
                    break;
            }
            switch (gTransition.actionWet) {
                case EF_ACTION_UP:
                    if (gTransition.activeWet >= gTransition.targetWet) {
                        gTransition.actionWet = EF_ACTION_NONE;
                    } else {
                        gTransition.activeWet += kChangeVal;
                    }
                    break;

                case EF_ACTION_DOWN:
                    if (gTransition.activeWet <= gTransition.targetWet) {
                        gTransition.actionWet = EF_ACTION_NONE;
                    } else {
                        gTransition.activeWet -= kChangeVal;
                    }
                    break;
            }
            switch (gTransition.actionRecordWet) {
                case EF_ACTION_UP:
                    if (gTransition.activeRecordWet >= gTransition.targetRecordWet) {
                        gTransition.actionRecordWet = EF_ACTION_NONE;
                    } else {
                        gTransition.activeRecordWet += kChangeVal;
                    }
                    break;

                case EF_ACTION_DOWN:
                    if (gTransition.activeRecordWet <= gTransition.targetRecordWet) {
                        gTransition.actionRecordWet = EF_ACTION_NONE;
                    } else {
                        gTransition.activeRecordWet -= kChangeVal;
                    }
                    break;
            }
            if ((gTransition.actionDry == EF_ACTION_NONE) && (gTransition.actionWet == EF_ACTION_NONE) && (gTransition.actionRecordWet == EF_ACTION_NONE)) {
                Menu targetMenu;
                EncoderFunc targetFunc;
                switch (gTransition.mode) {
                    case EF_MODE_NONE:
                        gTransition.active = false;
                        gTransition.mode = EF_MODE_NONE;
                        gTransition.phase = EF_PHASE_NONE;
                        transitionClearFlag = true;
                        break;

                    case EF_MODE_ACTIVE:
                        gTransition.active = false;
                        gTransition.mode = EF_MODE_NONE;
                        gTransition.phase = EF_PHASE_NONE;
                        transitionClearFlag = true;
                        (i == 0) ? checkMenuTransition(EFFECT_0_MENU, false) : checkMenuTransition(EFFECT_1_MENU, false);
                        (i == 0) ? checkEncoderTransition(ENC_EFFECT_0_ACTIVE, false) : checkEncoderTransition(ENC_EFFECT_1_ACTIVE, false);
                        break;

                    case EF_MODE_TYPE:

                    case EF_MODE_TIME:

                    case EF_MODE_FEEDBACK:
                        switch (gTransition.phase) {
                            case EF_PHASE_NONE:
                                gTransition.active = false;
                                gTransition.mode = EF_MODE_NONE;
                                gTransition.phase = EF_PHASE_NONE;
                                transitionClearFlag = true;
                                break;

                            case EF_PHASE_A:
                                switch (gTransition.mode) {
                                    case EF_MODE_TYPE:
                                        gTransition.activeType = gTransition.targetType;
                                        effect_updateMixFloats(i);
                                        break;

                                    case EF_MODE_TIME:
                                        switch (effect[i].type) {
                                            case EF_DELAY:
                                                effect[i].delay.time = kDelayTimeDataLibrary[effect[i].delay.aTime].data;
                                                effect[i].delay.update(rhythm.tempo);
                                                break;

                                            case EF_CHORUS:
                                                effect[i].chorus.time = kChorusTimeDataLibrary[effect[i].chorus.aTime].data;
                                                effect[i].chorus.update();
                                                break;

                                            case EF_FLANGER:
                                                effect[i].flanger.time = kFlangerTimeDataLibrary[effect[i].flanger.aTime].data;
                                                effect[i].flanger.update();
                                                break;
                                        }
                                        break;

                                    case EF_MODE_FEEDBACK:
                                        switch (effect[i].type) {
                                            case EF_CHORUS:
                                                effect[i].chorus.feedback = kChorusFeedbackDataLibrary[effect[i].chorus.bFeedback].data;
                                                effect[i].chorus.update();
                                                break;

                                            case EF_FLANGER:
                                                effect[i].flanger.feedback = kFlangerFeedbackDataLibrary[effect[i].flanger.bFeedback].data;
                                                effect[i].flanger.update();
                                                break;
                                        }
                                        break;
                                }
                                gTransition.phase = EF_PHASE_B;
                                gTransition.activeDry = 1.0;
                                gTransition.targetDry = 0.0;
                                gTransition.activeWet = 0.0;
                                gTransition.targetWet = 1.0;
                                gTransition.activeRecordWet = 0.0;
                                gTransition.targetRecordWet = 1.0;
                                effect_calculateGenTransition(i);
                                transitionShowFlag = 2;
                                if (i == 0) {
                                    targetMenu = EFFECT_0_MENU;
                                    switch (gTransition.mode) {
                                        case EF_MODE_TYPE:
                                            targetFunc = ENC_EFFECT_0_TYPE;
                                            break;

                                        case EF_MODE_TIME:
                                            targetFunc = ENC_EFFECT_0_PARAM_A;
                                            break;

                                        case EF_MODE_FEEDBACK:
                                            targetFunc = ENC_EFFECT_0_PARAM_B;
                                            break;
                                    }
                                } else {
                                    targetMenu = EFFECT_1_MENU;
                                    switch (gTransition.mode) {
                                        case EF_MODE_TYPE:
                                            targetFunc = ENC_EFFECT_1_TYPE;
                                            break;

                                        case EF_MODE_TIME:
                                            targetFunc = ENC_EFFECT_1_PARAM_A;
                                            break;

                                        case EF_MODE_FEEDBACK:
                                            targetFunc = ENC_EFFECT_1_PARAM_B;
                                            break;
                                    }
                                }
                                checkMenuTransition(targetMenu, true);
                                checkEncoderTransition(targetFunc, true);
                                break;

                            case EF_PHASE_B:
                                if (i == 0) {
                                    targetMenu = EFFECT_0_MENU;
                                    switch (gTransition.mode) {
                                        case EF_MODE_TYPE:
                                            targetFunc = ENC_EFFECT_0_TYPE;
                                            break;

                                        case EF_MODE_TIME:
                                            targetFunc = ENC_EFFECT_0_PARAM_A;
                                            break;

                                        case EF_MODE_FEEDBACK:
                                            targetFunc = ENC_EFFECT_0_PARAM_B;
                                            break;
                                    }
                                } else {
                                    targetMenu = EFFECT_1_MENU;
                                    switch (gTransition.mode) {
                                        case EF_MODE_TYPE:
                                            targetFunc = ENC_EFFECT_1_TYPE;
                                            break;

                                        case EF_MODE_TIME:
                                            targetFunc = ENC_EFFECT_1_PARAM_A;
                                            break;

                                        case EF_MODE_FEEDBACK:
                                            targetFunc = ENC_EFFECT_1_PARAM_B;
                                            break;
                                    }
                                }
                                gTransition.active = false;
                                gTransition.mode = EF_MODE_NONE;
                                gTransition.phase = EF_PHASE_NONE;
                                transitionClearFlag = true;
                                checkMenuTransition(targetMenu, false);
                                checkEncoderTransition(targetFunc, false);
                                break;
                        }
                        break;
                }
            }
        }
        if (effect[i].mixTransition.active) {
            Effect& effect_ = effect[i];
            EffectMixTransition& mTransition = effect[i].mixTransition;
            switch (mTransition.actionDry) {
                case EF_ACTION_UP:
                    if (effect_.dryFloat >= mTransition.targetDry) {
                        mTransition.actionDry = EF_ACTION_NONE;
                    } else {
                        effect_.dryFloat += kChangeVal;
                    }
                    break;

                case EF_ACTION_DOWN:
                    if (effect_.dryFloat <= mTransition.targetDry) {
                        mTransition.actionDry = EF_ACTION_NONE;
                    } else {
                        effect_.dryFloat -= kChangeVal;
                    }
                    break;
            }
            switch (mTransition.actionWet) {
                case EF_ACTION_UP:
                    if (effect_.wetFloat >= mTransition.targetWet) {
                        mTransition.actionWet = EF_ACTION_NONE;
                    } else {
                        effect_.wetFloat += kChangeVal;
                    }
                    break;

                case EF_ACTION_DOWN:
                    if (effect_.wetFloat <= mTransition.targetWet) {
                        mTransition.actionWet = EF_ACTION_NONE;
                    } else {
                        effect_.wetFloat -= kChangeVal;
                    }
                    break;
            }
            if ((mTransition.actionDry == EF_ACTION_NONE) && (mTransition.actionWet == EF_ACTION_NONE)) {
                mTransition.active = false;
            }
        }
    }

    // 7. REVERB TRANSITIONS
    // Process reverb generation/mix transitions and mode phase updates.
    if (reverb.genTransition.active) {
        ReverbGenTransition& gTransition = reverb.genTransition;
        switch (gTransition.actionDry) {
            case REV_ACTION_UP:
                if (gTransition.activeDry >= gTransition.targetDry) {
                    gTransition.actionDry = REV_ACTION_NONE;
                } else {
                    gTransition.activeDry += kChangeVal;
                }
                break;

            case REV_ACTION_DOWN:
                if (gTransition.activeDry <= gTransition.targetDry) {
                    gTransition.actionDry = REV_ACTION_NONE;
                } else {
                    gTransition.activeDry -= kChangeVal;
                }
                break;
        }
        switch (gTransition.actionWet) {
            case REV_ACTION_UP:
                if (gTransition.activeWet >= gTransition.targetWet) {
                    gTransition.actionWet = REV_ACTION_NONE;
                } else {
                    gTransition.activeWet += kChangeVal;
                }
                break;

            case REV_ACTION_DOWN:
                if (gTransition.activeWet <= gTransition.targetWet) {
                    gTransition.actionWet = REV_ACTION_NONE;
                } else {
                    gTransition.activeWet -= kChangeVal;
                }
                break;
        }
        if ((gTransition.actionDry == REV_ACTION_NONE) && (gTransition.actionWet == REV_ACTION_NONE)) {
            switch (gTransition.mode) {
                case REV_MODE_NONE:
                    gTransition.active = false;
                    gTransition.mode = REV_MODE_NONE;
                    gTransition.phase = REV_PHASE_NONE;
                    transitionClearFlag = true;
                    break;

                case REV_MODE_ACTIVE:
                    gTransition.active = false;
                    gTransition.mode = REV_MODE_NONE;
                    gTransition.phase = REV_PHASE_NONE;
                    transitionClearFlag = true;
                    checkMenuTransition(REVERB_MENU, false);
                    checkEncoderTransition(ENC_REVERB_ACTIVE, false);
                    break;

                case REV_MODE_PREDELAY:
                    switch (gTransition.phase) {
                        case REV_PHASE_NONE:
                            gTransition.active = false;
                            gTransition.mode = REV_MODE_NONE;
                            gTransition.phase = REV_PHASE_NONE;
                            transitionClearFlag = true;
                            break;

                        case REV_PHASE_A:
                            reverb.setPreDelay(kReverbPreDelayDataLibrary[reverb.preDelay].data);
                            gTransition.phase = REV_PHASE_B;
                            gTransition.activeDry = 1.0;
                            gTransition.targetDry = 0.0;
                            gTransition.activeWet = 0.0;
                            gTransition.targetWet = 1.0;
                            reverb_calculateGenTransition();
                            transitionShowFlag = 2;
                            checkMenuTransition(REVERB_MENU, true);
                            checkEncoderTransition(ENC_REVERB_PREDELAY, true);
                            break;

                        case REV_PHASE_B:
                            gTransition.active = false;
                            gTransition.mode = REV_MODE_NONE;
                            gTransition.phase = REV_PHASE_NONE;
                            transitionClearFlag = true;
                            checkMenuTransition(REVERB_MENU, false);
                            checkEncoderTransition(ENC_REVERB_PREDELAY, false);
                            break;
                    }
                    break;

                case REV_MODE_SURROUND:
                    switch (gTransition.phase) {
                        case REV_PHASE_NONE:
                            gTransition.active = false;
                            gTransition.mode = REV_MODE_NONE;
                            gTransition.phase = REV_PHASE_NONE;
                            transitionClearFlag = true;
                            break;

                        case REV_PHASE_A:
                            reverb.setSurround(kReverbSurroundDataLibrary[reverb.surround].data);
                            gTransition.phase = REV_PHASE_B;
                            gTransition.activeDry = 1.0;
                            gTransition.targetDry = 0.0;
                            gTransition.activeWet = 0.0;
                            gTransition.targetWet = 1.0;
                            reverb_calculateGenTransition();
                            transitionShowFlag = 2;
                            checkMenuTransition(REVERB_MENU, true);
                            checkEncoderTransition(ENC_REVERB_SURROUND, true);
                            break;

                        case REV_PHASE_B:
                            gTransition.active = false;
                            gTransition.mode = REV_MODE_NONE;
                            gTransition.phase = REV_PHASE_NONE;
                            transitionClearFlag = true;
                            checkMenuTransition(REVERB_MENU, false);
                            checkEncoderTransition(ENC_REVERB_SURROUND, false);
                            break;
                    }
                    break;
            }
        }
    }
    if (reverb.mixTransition.active) {
        ReverbMixTransition& mTransition = reverb.mixTransition;
        switch (mTransition.actionDry) {
            case REV_ACTION_UP:
                if (reverb.dryFloat >= mTransition.targetDry) {
                    mTransition.actionDry = REV_ACTION_NONE;
                } else {
                    reverb.dryFloat += kChangeVal;
                }
                break;

            case REV_ACTION_DOWN:
                if (reverb.dryFloat <= mTransition.targetDry) {
                    mTransition.actionDry = REV_ACTION_NONE;
                } else {
                    reverb.dryFloat -= kChangeVal;
                }
                break;
        }
        switch (mTransition.actionWet) {
            case REV_ACTION_UP:
                if (reverb.wetFloat >= mTransition.targetWet) {
                    mTransition.actionWet = REV_ACTION_NONE;
                } else {
                    reverb.wetFloat += kChangeVal;
                }
                break;

            case REV_ACTION_DOWN:
                if (reverb.wetFloat <= mTransition.targetWet) {
                    mTransition.actionWet = REV_ACTION_NONE;
                } else {
                    reverb.wetFloat -= kChangeVal;
                }
                break;
        }
        if ((mTransition.actionDry == REV_ACTION_NONE) && (mTransition.actionWet == REV_ACTION_NONE)) {
            mTransition.active = false;
        }
    }
}

void Controller::interruptSystemPreset() {
    /// @brief Finalizes the system-wide preset adjustment window by stopping the timeout timer and signaling a persistent storage write operation if changes were made.

    // 1. SYSTEM PRESET TIMER STOP
    // Stop the inactivity timer used during system preset edits.
    stopSystemPresetTimer();

    // 2. DEFERRED SAVE SIGNAL
    // Request a deferred NVM save when preset data has pending changes.
    if (systemPresetSaveActive) {
        systemPresetSaveFlag = true;
    }
}

void Controller::interruptEncoderPreset() {
    /// @brief Finalizes the encoder preset adjustment window by halting the preset timer and signaling a deferred save operation if the save state is active.

    // 1. ENCODER PRESET TIMER STOP
    // Stop the inactivity timer used during encoder preset edits.
    stopEncoderPresetTimer();

    // 2. DEFERRED SAVE SIGNAL
    // Request a deferred save when encoder preset data is marked dirty.
    if (encoderPresetSaveActive)
        encoderPresetSaveFlag = true;
}

void Controller::interruptLayerKeypadRead() {
    /// @brief Signals a hardware interrupt event from the layer keypad by setting a read request flag for the main processing loop.

    // 1. LAYER KEYPAD READ FLAG
    // Set read flag so keypad scanning runs in non-interrupt context.
    keyboard.keyLayer.readFlag = true;
}

void Controller::interruptLeftKeypadRead() {
    /// @brief Signals a hardware interrupt event from the left keypad by setting a read request flag for the main processing loop.

    // 1. LEFT KEYPAD READ FLAG
    // Set read flag so keypad scanning runs in non-interrupt context.
    keyboard.keyLeft.readFlag = true;
}

void Controller::interruptRightKeypadRead() {
    /// @brief Signals a hardware interrupt event from the right keypad by setting a read request flag for the main processing loop.

    // 1. RIGHT KEYPAD READ FLAG
    // Set read flag so keypad scanning runs in non-interrupt context.
    keyboard.keyRight.readFlag = true;
}

void Controller::interruptEncoderRead(uint8_t encNum_) {
    /// @brief Sets a read request flag for a specific rotary encoder to signal the main processing loop that a hardware interrupt has occurred.

    Encoder& enc = encoder[encNum_];

    // 1. CAPTURE AB
    // Read Phase A and B pins immediately
    uint8_t a = (enc.aPort->IDR & enc.aPin) ? 2 : 0;
    uint8_t b = (enc.bPort->IDR & enc.bPin) ? 1 : 0;
    enc.capturedAB = (a | b);  // Store the snapshot

    // 2. ENCODER READ FLAG
    // Set selected encoder read flag for deferred processing.
    enc.readFlag = true;
}

void Controller::interruptFuncButtonRead() {
    /// @brief Manages navigation through factory test modes by handling function button interrupts, coordinating UI updates, and initializing hardware peripherals for each test stage.

    static uint32_t lastReliableTick = 0;

    // 1. MENU & DEBOUNCE VALIDATION
    // Continue only in test menu and after debounce window expires.
    if ((menu == TEST_MENU) && ((HAL_GetTick() - lastReliableTick) > 10)) {
        // 2. TEST MODE STATE TRANSITION
        // Dispatch function-button action based on current test mode.
        switch (testMode) {
            case TEST_NONE:
                break;

            case TEST_SCREEN:
                // TRANSITION: SCREEN -> KEY TEST
                // Switch from display test to key/input test stage.
                testMode = TEST_KEY;

                // Clear all MCP23017 LED expanders before switching modes
                i2c4_txData[0] = 0x00;
                i2c4_txData[1] = 0x00;
                HAL_I2C_Mem_Write(&hi2c4, ledEqLeft.address, MCP23017_GPIOA, I2C_MEMADD_SIZE_8BIT, i2c4_txData, 2, 1);
                HAL_I2C_Mem_Write(&hi2c4, ledEqRight.address, MCP23017_GPIOA, I2C_MEMADD_SIZE_8BIT, i2c4_txData, 2, 1);
                HAL_I2C_Mem_Write(&hi2c4, ledLayer.address, MCP23017_GPIOA, I2C_MEMADD_SIZE_8BIT, i2c4_txData, 2, 1);

                // Re-initialize input peripherals for testing
                encoder_initialize();
                keyboard_initialize();
                lcd_test(testMode);
                break;

            case TEST_KEY:
                // TRANSITION: KEY -> AUDIO TEST
                // Switch to audio path verification stage.
                testMode = TEST_AUDIO;
                lcd_test(testMode);
                io_setSyncOut(2);         // Enable MODE-B sync output for test mode
                io.midi.txActive = true;  // Enable MIDI TX for test mode
                io.midi.txClock = true;   // Enable MIDI clock (0xF8) TX only
                io.midi.txTransport = false;
                record();                 // Start looped recording so the sequencer clock runs
                break;

            case TEST_AUDIO:
                // TRANSITION: AUDIO -> SYNC TEST
                // Switch to synchronization verification stage.
                // Sync output is already active from TEST_AUDIO; MIDI notes continue via interruptPlay.
                testMode = TEST_SYNC;
                lcd_test(testMode);
                break;

            case TEST_SYNC:
                // TRANSITION: SYNC -> END/RESET
                // Finalize test flow and trigger full system reset.
                testMode = TEST_END;
                lcd_test(testMode);
                reset();
                NVIC_SystemReset();  // Perform a full hardware reset after test completion
                break;

            case TEST_END:
                break;
        }

        // 3. DEBOUNCE TIMESTAMP UPDATE
        // Store the latest accepted button event tick.
        lastReliableTick = HAL_GetTick();
    }
}

void Controller::interruptUpKeyRead() {
    /// @brief Processes the up-key press event by managing a debounce counter and triggering the action flag under valid system conditions.

    // 1. PRESS COUNTER UPDATE
    // Increment debounce counter until stable press threshold is reached.
    if (keyboard.upKeyCounter < 2) {
        keyboard.upKeyCounter += 1;
    }

    // 2. ACTION FLAG VALIDATION
    // Trigger action only when no alert/conflicting key state is active.
    else if ((!alertFlag) && (keyboard.upKeyFlag) && (!keyboard.downKeyFlag)) {
        keyboard.upActionFlag = true;
    }
}

void Controller::interruptDownKeyRead() {
    /// @brief Processes the down-key press event by managing a debounce counter and triggering the action flag under valid system conditions.

    // 1. PRESS COUNTER UPDATE
    // Increment debounce counter until stable press threshold is reached.
    if (keyboard.downKeyCounter < 2) {
        keyboard.downKeyCounter += 1;
    }

    // 2. ACTION FLAG VALIDATION
    // Trigger action only when no alert/conflicting key state is active.
    else if ((!alertFlag) && (keyboard.downKeyFlag) && (!keyboard.upKeyFlag)) {
        keyboard.downActionFlag = true;
    }
}

void Controller::interruptLongKeyRead() {
    /// @brief Processes long-press keyboard events by managing a duration counter and triggering specific system actions like muting, copying, or resetting when the timing threshold is exceeded.

    // 1. LONG-PRESS COUNTER UPDATE
    // Increment counter until long-press threshold is reached.
    if (keyboard.longKeyCounter < kLongKeyCountHigh) {
        keyboard.longKeyCounter += 1;
    } else {
        // 2. LONG-PRESS ACTION DISPATCH
        // Execute action mapped to the currently active long-press flag.

        // RHYTHM LOCK/UNLOCK ACTIONS
        // Handle long-press actions related to rhythm lock state.
        if (rhythmUnlockKeyFlag) {
            stopLongKeyTimer();
            keyboard.longKeyCounter = 0;
            rhythmUnlockKeyFlag = false;
            rhythmUnlockActionFlag = true;
        } else if (rhythmLockKeyFlag) {
            stopLongKeyTimer();
            keyboard.longKeyCounter = 0;
            rhythmLockKeyFlag = false;
            rhythmLockActionFlag = true;
        }

        // MASTER/OUTPUT MUTE ACTIONS
        // Handle long-press actions related to mute/unmute controls.
        else if (masterUnmuteKeyFlag) {
            stopLongKeyTimer();
            keyboard.longKeyCounter = 0;
            masterUnmuteKeyFlag = false;
            masterUnmuteActionFlag = true;
        } else if (masterMuteKeyFlag) {
            stopLongKeyTimer();
            keyboard.longKeyCounter = 0;
            masterMuteKeyFlag = false;
            masterMuteActionFlag = true;
        } else if (hpUnmuteKeyFlag) {
            stopLongKeyTimer();
            keyboard.longKeyCounter = 0;
            hpUnmuteKeyFlag = false;
            hpUnmuteActionFlag = true;
        } else if (hpMuteKeyFlag) {
            stopLongKeyTimer();
            keyboard.longKeyCounter = 0;
            hpMuteKeyFlag = false;
            hpMuteActionFlag = true;
        } else if (loUnmuteKeyFlag) {
            stopLongKeyTimer();
            keyboard.longKeyCounter = 0;
            loUnmuteKeyFlag = false;
            loUnmuteActionFlag = true;
        } else if (loMuteKeyFlag) {
            stopLongKeyTimer();
            keyboard.longKeyCounter = 0;
            loMuteKeyFlag = false;
            loMuteActionFlag = true;
        } else if (liUnmuteKeyFlag) {
            stopLongKeyTimer();
            keyboard.longKeyCounter = 0;
            liUnmuteKeyFlag = false;
            liUnmuteActionFlag = true;
        } else if (liMuteKeyFlag) {
            stopLongKeyTimer();
            keyboard.longKeyCounter = 0;
            liMuteKeyFlag = false;
            liMuteActionFlag = true;
        }

        // LFO CLIPBOARD/RESET ACTIONS
        // Handle long-press actions for LFO copy, paste, and reset.
        else if (lfoCopyKeyFlag) {
            stopLongKeyTimer();
            keyboard.longKeyCounter = 0;
            lfoCopyKeyFlag = false;
            if (selectedLfoNum != -1) {
                lfoCopyActionFlag = true;
                textCopyFlag = true;
            }
        } else if (lfoPasteKeyFlag) {
            stopLongKeyTimer();
            keyboard.longKeyCounter = 0;
            lfoPasteKeyFlag = false;
            if ((lfoCopy.copyActive) && (selectedLfoNum != -1)) {
                lfoPasteActionFlag = true;
                textPasteFlag = true;
            }
        } else if (lfoResetKeyFlag) {
            stopLongKeyTimer();
            keyboard.longKeyCounter = 0;
            lfoResetKeyFlag = false;
            lfoResetActionFlag = true;
        }

        // LAYER INSTRUMENT ACTIONS
        // Handle long-press actions for layer instrument copy/paste/reset.
        else if (layerInstCopyKeyFlag) {
            stopLongKeyTimer();
            keyboard.longKeyCounter = 0;
            layerInstCopyKeyFlag = false;
            if (selectedLayerNum != -1) {
                layerInstCopyActionFlag = true;
                textCopyFlag = true;
            }
        } else if (layerInstPasteKeyFlag) {
            stopLongKeyTimer();
            keyboard.longKeyCounter = 0;
            layerInstPasteKeyFlag = false;
            if ((layerInstCopy.copyActive) && (selectedLayerNum != -1)) {
                layerInstPasteActionFlag = true;
                textPasteFlag = true;
            }
        } else if (layerInstResetKeyFlag) {
            stopLongKeyTimer();
            keyboard.longKeyCounter = 0;
            layerInstResetKeyFlag = false;
            layerInstResetActionFlag = true;
        }

        // LAYER SONG ACTIONS
        // Handle long-press actions for layer song copy/paste/reset.
        else if (layerSongCopyKeyFlag) {
            stopLongKeyTimer();
            keyboard.longKeyCounter = 0;
            layerFillCopyKeyFlag = false;
            layerSongCopyKeyFlag = false;
            if (selectedLayerNum != -1) {
                layerSongCopyActionFlag = true;
                textCopyFlag = true;
            }
        } else if (layerSongPasteKeyFlag) {
            stopLongKeyTimer();
            keyboard.longKeyCounter = 0;
            layerFillPasteKeyFlag = false;
            layerSongPasteKeyFlag = false;
            if ((layerSongCopy.copyActive) && selectedLayerNum != -1) {
                layerSongPasteActionFlag = true;
                textPasteFlag = true;
            }
        } else if (layerSongResetKeyFlag) {
            stopLongKeyTimer();
            keyboard.longKeyCounter = 0;
            layerSongResetKeyFlag = false;
            if (selectedLayerNum != -1) {
                layerSongResetActionFlag = true;
            }
        }

        // MULTI-STAGE BEAT GENERATION
        // Cycle beat-generation presets on repeated long-press steps.
        else if (layerBeatKeyFlag) {
            keyboard.longKeyCounter = 0;
            switch (layerBeatKeyStage) {
                case 0:
                    layerSong_generateBeat(0);
                    layerBeatKeyStage = 1;
                    break;

                case 1:
                    layerSong_generateBeat(1);
                    layerBeatKeyStage = 2;
                    break;

                case 2:
                    layerSong_generateBeat(2);
                    layerBeatKeyStage = 3;
                    break;

                case 3:
                    // Apply BASIC_4 fill to all beats (4 hits per beat).
                    layerSong_generateBeat(3);
                    layerBeatKeyStage = 4;
                    break;

                case 4:
                    // Apply BASIC_8 fill to all beats (8 hits per beat).
                    layerSong_generateBeat(4);
                    layerBeatKeyFlag = false;
                    stopLongKeyTimer();
                    keyboard.longKeyCounter = 0;
                    break;
            }
        } else {
            // Default: Reset and stop if no valid flag is identified
            stopLongKeyTimer();
            keyboard.longKeyCounter = 0;
        }
    }
}

void Controller::interruptText() {
    /// @brief Toggles the text visibility state or triggers a system flag to clear the displayed text after the visibility timer expires.

    // 1. TEXT VISIBILITY STATE
    // Toggle text display state or complete text timeout handling.
    if (textShow) {
        // Disable visibility for the current display cycle
        textShow = false;
    } else {
        // 2. TEXT SESSION TERMINATION
        // Stop timer and request text clear operation.
        stopTextTimer();

        // Signal the UI controller to wipe the text from the display
        textClearFlag = true;
    }
}

void Controller::interruptLedEq() {
    /// @brief Triggers playback flags to synchronize LED visualization updates with the active EQ processing cycles.

    // 1. EQ LED READ FLAGS
    // Mark both EQ LED channels ready for visualization update.
    ledEqReadFlag[0] = true;
    ledEqReadFlag[1] = true;
}

void Controller::interruptSd() {
    /// @brief Monitors the physical presence of the SD card and handles emergency removal by closing active files, unmounting the file system, and notifying the UI.

    // 1. SD REMOVAL DETECTION
    // Detect unexpected SD card removal using hardware detect signal.
    if ((sd.detect) && (sd_detect() == SD_ERROR)) {
        // 2. FILE SYSTEM SHUTDOWN
        // Close active file handle and unmount SD interface safely.
        f_close(&sd.file);

        // Detach the SD card driver from the system
        sd_unmount();

        // 3. STATE & UI ALERT UPDATE
        // Reset SD flags and notify UI about removal condition.
        sd.detect = false;
        sd.ready = false;

        // Display a critical error message on the LCD for the user
        lcd_drawSdAlert(SD_ERROR_DETECT);
    }
}

void Controller::interruptBeatSync() {
    /// @brief Terminates the beat synchronization output signal and halts the dedicated hardware timer to stop clock pulse generation.

    // 1. SYNC OUTPUT STOP
    // Pull sync output line low to terminate active pulse.
    HAL_GPIO_WritePin(SYNC_OUT_PULSE_GPIO_Port, SYNC_OUT_PULSE_Pin, GPIO_PIN_RESET);

    // 2. SYNC TIMER STOP
    // Stop beat-sync timer to prevent further pulse interrupts.
    stopBeatSyncTimer();
}

void Controller::interruptLimitAlert() {
    /// @brief Disables the limit alert timer and triggers the flag to clear active limit notifications from the system.

    // 1. ALERT TIMER STOP
    // Stop limit-alert timer to end timed alert phase.
    stopLimitAlertTimer();

    // 2. ALERT CLEAR FLAG
    // Request UI/system to clear limit alert state on next cycle.
    limitAlertClearFlag = true;
}